/* ============================================================================
   新聞內文匯入（資料遷移，S2-27 ④／C-1）
   2026-10-15｜來源：客戶 Google Drive 的新聞文稿（TCRFC_資料收件夾/07_NEWS 各資料夾內 .gdoc／.gsheet 的 doc_id），
   以 claude.ai Google Drive 連接器讀取，轉為區塊 JSON {"blocks":[…]}（docs/14 新聞 body 格式）。共 83 篇。
   文件類 77 篇——只做格式處理、不改寫：空行分段、段內換行保留、去掉 Markdown 粗體記號、"# " 開頭的單行轉小標。
     - 讀取工具遇到擴充區漢字會輸出亂碼並吃掉文末字元，三篇以 text/plain 匯出的原始位元組核對：
       2026-04-18-match-010 還原「許𣁽」（U+2307D）與被截掉的替補「51 陳牧恩」；
       2024-12-18-club-080、2025-12-22-match-018 原文為「𥚃面」（U+25683，「裡」的異體，多數字型無此字），寫為「裡面」。
   試算表類 6 篇（7.9 國際盃）——表格原樣重排為：賽事資訊、比分（或「比賽取消」）、進球、比賽資料、兩隊先發與替補名單。
   標題修正 2 篇：2025-12-14-match-020、2025-12-09-match-021 的收件夾資料夾名稱誤寫為「企甲 台灣電力 1-2」，
     內文實為兩場乙級聯賽，標題改以 Google 文件標題為準（中英各一列；僅在標題仍為舊值時更新）。
     種子來源 site/src/data/news.json 與 db/seed/en_backfill_seed.py 已同步修正。
   只更新 zh-Hant 且 body IS NULL 的列——後台已編輯過的文章不覆蓋；🔴 冪等，可重複執行。英文內文不填。
   內容均為客戶提供、預定公開發布的新聞稿。
   執行：sqlcmd -S <server> -d tcrfc_club -b -I -i db/migrations/20261015_news-body-import.sql
   ============================================================================ */
SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRAN;
DECLARE @n int = 0;
UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "台中磐石足球俱樂部在8月4日率領10名青訓球員及4名教練，前往斯洛伐克展開為期一週的交流行程，與當地職業俱樂部AS Trenčín就青訓體系、教練培育及球員發展等面向進行深度交流，是俱樂部國際發展計畫中重要的一步。"}, {"type": "paragraph", "text": "此次行程延續雙方過去數月建立的良好互動。先前台中磐石代表曾造訪AS Trenčín青訓學院，了解其訓練架構與培育理念，並就未來合作交換想法。本次由教練與球員親自前往，則是將交流真正落實到球場之上。"}, {"type": "paragraph", "text": "一週期間，台中磐石球員依年齡與發展階段，編入AS Trenčín青年梯隊，與當地球員一同訓練。從訓練節奏的適應、與陌生隊友的溝通，到面對不同足球文化的調整，都是球員成長路上難能可貴的經驗。"}, {"type": "paragraph", "text": "此行另一重點，是雙方教練團之間的專業交流。在AS Trenčín青年隊體育總監Marek Dobiáš及青訓團隊的安排下，台中磐石教練團深入了解該俱樂部在球員培育、訓練規劃及各階段發展策略上的做法，雙方並透過觀摩與討論交換寶貴經驗。"}, {"type": "paragraph", "text": "台中磐石俱樂部在此特別感謝AS Trenčín、Marek Dobiáš 體育總監及整個青訓團隊，在本次行程中給予的熱情接待與全力協助。從訓練安排、教練交流到球員融入梯隊，每一環節都讓此行得以圓滿，也讓參與球員與教練收穫珍貴的學習經驗。"}, {"type": "paragraph", "text": "本次斯洛伐克之行，是雙方合作邁向下一階段的重要里程碑。未來雙方將持續在青訓發展、教練交流及球員培育等領域保持聯繫，AS Trenčín 團隊也規劃於近期訪台，進一步了解台中磐石的俱樂部與青訓運作。"}, {"type": "paragraph", "text": "台中磐石期待以此次交流為基礎，與AS Trenčín逐步建立更深入且長遠的夥伴關係，為兩地青年球員及教練創造更多學習與成長的機會。"}, {"type": "paragraph", "text": "再次誠摯感謝AS Trenčín、Marek Dobiáš體育總監及青訓團隊一路以來的支持與配合，期待下一次在台灣相見。"}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2026-08-10-international-000' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "2026/05/24 西屯足球場"}, {"type": "paragraph", "text": "企甲聯賽 Week 21：台中磐石 3-0 銘傳大學"}, {"type": "paragraph", "text": "進球：\n張恒 42''"}, {"type": "paragraph", "text": "施靖堂 70'' 82''"}, {"type": "paragraph", "text": "5月24日，台灣企業甲級足球聯賽第21輪收官戰，台中磐石主場以3比0擊敗銘傳大學，張恒與施靖堂各自建功，以勝利為本賽季畫下句號。"}, {"type": "paragraph", "text": "上半場台中磐石主導局面，惟把握機會欠佳。第10分鐘，張恒奪得球權後在右路底線前傳中，先發登場的古傑安在禁區邊緣射門，惟被銘傳守門員積遜接住。第34分鐘，龔致宇穿越球送進禁區為劉建緯創造機會，後者窄角度右腳抽射惟未能命中。第42分鐘，台中磐石終於打破僵局，周宇豪利用速度在左路快速下底傳中，張恒在禁區內左腳破門，取得生涯中首個企甲進球，台中磐石以1比0進入中場休息。"}, {"type": "paragraph", "text": "下半場銘傳大學積極反撲。第50分鐘，朱其龍把握台中磐石傳球失誤，在禁區邊緣左腳抽射高出。第57分鐘，安哲羅穿越球送前，朱其龍內切右腳射門，惟被門將蔡宇翔擋出。台中磐石隨即作出回應，第65分鐘，周宇豪再度在左路下底傳中，龔致宇衝前射門惟高出球門。第70分鐘，魏志荃短傳找到無人盯防的施靖堂，後者右腳抽射破門，將優勢擴大至2比0。第82分鐘，周宇杰一記精準穿越球撕開對手防線，劉建緯在禁區內傳中至遠點，施靖堂左腳推射破門梅開二度，鎖定3比0勝局。"}, {"type": "paragraph", "text": "第91分鐘，銘傳吳倍希在禁區邊緣大力左腳抽射，蔡宇翔及時擋出，守住球門不失。台中磐石以3比0完勝銘傳大學，在收官戰畫下圓滿句號。"}, {"type": "paragraph", "text": "先發陣容 : 4 蔡俊昇 5 周宇杰 7 龔致宇 9 劉建緯 10 張恒 19 周宇豪 21 古傑安 32 柯岳廷 48 王義友 88 廖奕盛 99 蔡宇翔"}, {"type": "paragraph", "text": "替補 : 1 黃懷賢 2 鄭凱議 6 孫恩祈 12 李毓霖 16 魏志荃 27 施靖堂 35 李鴻均 37 梁顥騰 44 山內大空 47 高冠宇 66 曾畇浩 77 林偉傑"}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2026-05-24-match-001' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "2026/05/17 西屯足球場"}, {"type": "paragraph", "text": "企甲聯賽 Week 20：台中磐石 1-2 陽信北競"}, {"type": "paragraph", "text": "進球： 黃偉傑 53'' (北競) 內田潤 68'' (北競) 周宇杰 90+7''"}, {"type": "paragraph", "text": "台灣企業甲級足球聯賽第20輪賽事17日登場，台中磐石主場迎戰陽信北競，雖在傷停補時第7分鐘由周宇杰遠射破門，惟最終仍以1比2落敗，主場三分拱手相讓。"}, {"type": "paragraph", "text": "上半場雙方均有機會。第12分鐘，台中磐石首次製造射門機會，魏志荃主罰自由球擊中對手後彈出底線。第23分鐘，陽信北競發動進攻，內田潤左路傳中，黃偉傑在後點擺脫後射門，惟未能命中目標。第39分鐘，山內大空在禁區邊緣為自己製造空間後起腳遠射，被對手門將擋出，上半場雙方以0比0進入中場休息。"}, {"type": "paragraph", "text": "下半場第53分鐘，陽信北競右路傳中球擊中台中磐石李毓霖手部，裁判當即判罰十二碼，黃偉傑主罰一蹴而就，陽信北競率先取得領先。第68分鐘，陽信北競再度發動突擊，內田潤左腳射門途中擊中曾畇浩，足球改變方向反彈入網，北競將優勢擴大至2比0。第81分鐘，陽信北競陳宥霖主罰自由球送入禁區，黃偉傑頭槌攻門擊中門柱，未能再下一城。"}, {"type": "paragraph", "text": "台中磐石最後階段展開猛攻。同樣在第81分鐘，山內大空與龔致宇連線後起腳遠射。第88分鐘，劉建緯在禁區內抽射，惟被門將接住。第90分鐘，柯岳廷右路傳中，山內大空頭球攻門偏出。直到傷停補時第7分鐘，林偉傑在禁區內盤帶後短傳至禁區邊緣，周宇杰遠射破門扳回一城，惟已無力回天。最終台中磐石以1比2不敵陽信北競，主場吞下敗仗。"}, {"type": "paragraph", "text": "先發陣容 : 6 孫恩祈 7 龔致宇 9 劉建緯 12 李毓霖 16 魏志荃 35 李鴻均 37 梁顥騰 44 山內大空 48 王義友(C) 66 曾畇浩 99 蔡宇翔"}, {"type": "paragraph", "text": "替補 : 1 黃懷賢, 2 鄭凱議, 4 蔡俊昇, 5 周宇杰, 10 張恒, 19 周宇豪 21 古傑安, 27 施靖堂, 32 柯岳廷, 77 林偉傑, 88 廖奕盛"}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2026-05-17-match-002' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "2026/05/10 西屯足球場"}, {"type": "paragraph", "text": "企甲聯賽 Week 19：台中磐石 2-4 南市台鋼"}, {"type": "paragraph", "text": "進球： 3'' 24'' 金湘俊(台鋼) 16'' 劉建緯"}, {"type": "paragraph", "text": "18'' 班吉(台鋼) 49'' 山內大空 90'' 吳俊青"}, {"type": "paragraph", "text": "5月10日，台灣企業甲級足球聯賽第19輪賽事，台中磐石於楠梓足球場迎戰南市台鋼，雖曾一度追平，終以2比4落敗，未能帶走積分。賽後台中磐石以19戰積27分，位列積分榜第五位。"}, {"type": "paragraph", "text": "開場第3分鐘，台鋼便率先取得領先，班吉與金湘俊快速連線推進，金湘俊單刀冷靜破門。台中磐石隨即作出回應，第16分鐘，李毓霖長傳助攻劉建緯，後者胸部停球後右腳射門得分，迅速追平比分至1比1。然而第18分鐘台鋼長距離邊線球送入禁區，班吉在禁區內混戰中破門，台鋼重新取得領先。第24分鐘，艾斯特長傳為金湘俊創造機會，後者左腳抽射得分梅開二度，台鋼以3比1的優勢進入中場休息。"}, {"type": "paragraph", "text": "下半場第49分鐘，艾斯特在禁區內拉倒替補登場的林偉傑，裁判當即判罰十二碼罰球，山內大空主罰一蹴而就，取得個人本賽季第七個進球，為台中磐石追近比分至2比3。第59分鐘，台中磐石獲得禁區邊緣自由球，山內大空親自主罰，惟足球偏出球門。第60分鐘，台鋼發動快速反擊，姚克錡傳中至後點，班吉接應回傳左腳抽射，台中磐石守門員蔡宇翔及時將球擋出。"}, {"type": "paragraph", "text": "此後台中磐石持續透過換人調動尋求突破，惟多次進攻均無功而返。第90分鐘，台鋼沿左路推進，林明偉在禁區內為吳俊青送出助攻，後者右腳射門得分，將最終比分鎖定為2比4。台中磐石以2比4吞下敗仗，楠梓足球場未能帶走積分。"}, {"type": "paragraph", "text": "先發陣容 : 4 蔡俊昇 5 周宇杰 6 孫恩祈 7 龔致宇 9 劉建緯 12 李毓霖 19 周宇豪 32 柯岳廷 44 山內大空 48 王義友(C) 99 蔡宇翔 替補 : 1 黃懷賢 2 鄭凱議 10 張恒 21 古傑安 27 施靖堂 35 李鴻均 66 曾畇浩 77 林偉傑"}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2026-05-10-match-003' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "2026/05/09 迎風足球場"}, {"type": "paragraph", "text": "乙級聯賽 Week 14 ：陽信北競預備隊 5-0 台中磐石預備隊"}, {"type": "paragraph", "text": "進球: 狩野蒼太 23’ 33’ 黃常滔 41’ 蔡孟光 43’ 楊羅德 85’"}, {"type": "paragraph", "text": "台灣乙級足球聯賽第14輪賽事9日於迎風足球場進行，台中磐石預備隊以0比5敗給陽信北競預備隊，以12戰積分17分完成25/26賽季乙級聯賽全部賽程。"}, {"type": "paragraph", "text": "台中磐石預備隊開場率先發動攻勢，第14分鐘，右路邊線球開出後傳中至後點，戴彥堯起腳射門，惟被對手門將近距離擋出。然而此後賽局完全被地主陽信北競掌控。第23分鐘，楊羅德在右路突破後傳中，狩野蒼太搶點破門，北競率先取得領先。第33分鐘，北競複製相同進球套路，楊羅德再度傳中至後點，狩野蒼太趕至射門得分，將比分擴大至2比0。"}, {"type": "paragraph", "text": "第41分鐘，楊羅德在禁區邊緣突破射門，台中磐石門將陳瑄廷將球撲出，惟黃常滔在禁區邊緣抽射破門，北競領先擴大至3比0。第43分鐘，北競再從角球機會中由蔡孟光射門得分，以4比0的領先優勢進入中場休息。"}, {"type": "paragraph", "text": "下半場第48分鐘，台中磐石預備隊嘗試反擊，許劉鑑鋒在前場搶得球權，江均堯穿越球送進禁區，李偉綸把握時機右腳抽射，可惜足球射中網外。第84分鐘，北競發動快速進攻，劉計超停球回傳，後上的陳銘哲左腳抽射，陳瑄廷再度撲出化解。然而第85分鐘，黃常滔在中場一記穿越球送進禁區，楊羅德突破越位陷阱單刀破門，將最終比分改寫為5比0。"}, {"type": "paragraph", "text": "台中磐石預備隊就此以12戰積分17分，完成本賽季乙級聯賽全部賽程。"}, {"type": "paragraph", "text": "先發陣容 : 3 許魁 8 陳柏穎 14 李偉綸 17 許劉鑑鋒 20 戴彥堯 26 林家樂 28 陳治瑋 33 許紘銘 29 江均堯(C) 30 陳瑄廷 79 嚴冠侑"}, {"type": "paragraph", "text": "替補 : 1 何乾愷 5 劉俊佑 13 陳柏崴 18 陳冠智 45 胡淯翔 25 薛任祐 51 陳牧恩"}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2026-05-09-match-004' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "2026/05/03 西屯足球場"}, {"type": "paragraph", "text": "乙級聯賽 Week 13 ：台中磐石預備隊 0-2 銘傳Desafio"}, {"type": "paragraph", "text": "進球："}, {"type": "paragraph", "text": "60’ 蘇明強 (Desafio)"}, {"type": "paragraph", "text": "90+6’ 傅鼎紘 (Desafio)"}, {"type": "paragraph", "text": "台灣乙級足球聯賽第13輪賽事，5月3日於西屯足球場進行，台中磐石預備隊主場以0比2敗給銘傳Desafio，未能取分。"}, {"type": "paragraph", "text": "上半場雙方均積極創造機會。台中磐石的首次攻勢來自禁區邊緣自由球，由江均堯主罰，惟未能命中目標。第23分鐘，銘傳Desafio打出流暢的短傳配合，蘇明強個人突破兩名後衛後將球橫傳右側，王俊丞跟進射門，可惜足球只打中網側。上半場末段台中磐石漸佔主動，第42分鐘，許劉鑑鋒在禁區邊緣回收球權後回傳，陳治瑋跟進然後左腳抽射，惟未能轉化為進球。上半場雙方以0比0進入中場休息。"}, {"type": "paragraph", "text": "下半場局面急轉直下。第61分鐘，銘傳Desafio獲判十二碼罰球，替補登場的門將何乾愷雖判斷方向正確，仍未能阻止蘇明強主罰破門，銘傳Desafio先馳得點。3分鐘後，銘傳Desafio再度獲判十二碼，蘇明強再次主罰，這次以挑射方式嘗試得分，惟足球未能進門。"}, {"type": "paragraph", "text": "落後一球的台中磐石預備隊全力反撲，惟攻勢同時令後防出現空隙，傷停補時第6分鐘，傅鼎紘把握機會單刀破門，將比分鎖定為2比0。終場前最後1分鐘，江均堯擺脫兩名防守球員後左腳抽射，惟被門將黃泊皓擋出。"}, {"type": "paragraph", "text": "最終台中磐石預備隊以0比2不敵銘傳Desafio，主場吞下敗仗。"}, {"type": "paragraph", "text": "先發陣容 : 8 陳柏穎 13 陳柏崴(C) 14 李偉綸 17 許劉鑑鋒 20 戴彥堯 22 黃昱博 23 盧恩偉 28 陳治瑋 29 江均堯 30 陳瑄廷 79 嚴冠侑"}, {"type": "paragraph", "text": "替補 : 1 何乾愷, 5 劉俊佑, 18 陳冠智, 25 薛任祐, 26 林家樂, 31 汪法華, 33 許紘銘 34 蔣汯家, 39 王宏宇, 40 林政睿, 42 曾偉亘, 45 胡淯翔, 51 陳牧恩"}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2026-05-03-match-005' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "2026/05/03 西屯足球場"}, {"type": "paragraph", "text": "企甲聯賽 Week 18：台中磐石 1-0 大同足球"}, {"type": "paragraph", "text": "進球："}, {"type": "paragraph", "text": "62’ 山內大空"}, {"type": "paragraph", "text": "5月3日，台灣企業甲級足球聯賽第18輪賽事，台中磐石主場迎戰大同足球，憑山內大空第61分鐘把握對手門將失誤破門，以1比0取得三分積分。"}, {"type": "paragraph", "text": "製造出全場第一個機會的事大同，第19分鐘，陳瑞杰在左路截得傳球後傳中禁區，游家煌左腳射門惟未能得分。第25分鐘，近來連線默契漸佳的山內大空與劉建緯再度配合，山內大空截得傳球後穿越球送進禁區，劉建緯右腳抽射，被大同門將東風淳飛身撲出。第29分鐘，台中磐石獲得自由球機會，周宇杰左腳開出球至禁區中央，山內大空飛身頭槌攻門，可惜未能命中。第39分鐘，周宇杰傳球向前，劉建緯在禁區內回傳，山內大空連續兩次射門均未能破門。上半場雙方均無記錄，0比0進入中場休息。"}, {"type": "paragraph", "text": "下半場第61分鐘，東風淳出球失誤，山內大空迅速斷球，隨即晃過出擊的東風淳冷靜破門，為台中磐石取得領先。第75分鐘，大同游家煌在右路推進後傳中，陳瑞杰趕至稍慢一步，在門前錯失機會。進入長達9分鐘的傷停補時，大同全力進攻。第91分鐘，魏沛倫左路突破後傳中，趙韋傑搶點左腳射門未能命中。第99分鐘，大同右路配合後由出水太陽傳中至後點，魏沛倫左腳抽射被擋出，台中磐石力保球門不失。"}, {"type": "paragraph", "text": "最終台中磐石以1比0擊敗大同，主場三分收入囊中，並且將失敗走勢延續至七場。"}, {"type": "paragraph", "text": "先發陣容 : 4 蔡俊昇 5 周宇杰 9 劉建緯 12 李毓霖 19 周宇豪 32 柯岳廷 35 李鴻均 37 梁顥騰 44 山內大空 48 王義友(C) 99 蔡宇翔"}, {"type": "paragraph", "text": "替補 : 1 黃懷賢, 2 鄭凱議, 6 孫恩祈, 7 龔致宇, 10 張恒, 16 魏志荃, 21 古傑安 27 施靖堂, 30 陳瑄廷, 47 高冠宇, 66 曾畇浩, 77 林偉傑, 88 廖奕盛"}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2026-05-03-match-006' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "2026/04/26 西屯足球場"}, {"type": "paragraph", "text": "企甲聯賽 Week 17：台中磐石 2-2 台電"}, {"type": "paragraph", "text": "進球："}, {"type": "paragraph", "text": "30’ 林晨 (台電)"}, {"type": "paragraph", "text": "58’ 賴維 (台電)"}, {"type": "paragraph", "text": "72’ 劉建緯"}, {"type": "paragraph", "text": "90+6’ 林偉傑"}, {"type": "paragraph", "text": "4月26日，台灣企業甲級足球聯賽第17輪賽事於西屯足球場進行，台中磐石一度落後兩球，最終憑林偉傑在傷停補時第6分鐘的抽射，以2比2逼平台電。"}, {"type": "paragraph", "text": "開場第12分鐘，台中磐石率先發動試探，張恒短傳找到劉建緯，後者突然起腳遠射，惟被台電門將穩穩接住。第19分鐘，台電把握左邊角球機會，林晨直接主罰破門，台電先馳得點。第42分鐘，台中磐石陳昭安嘗試倒掛射門，意外踢中蔡俊昇頭部，裁判出示本場第二張黃牌將其罰下，台電陷入十人應戰局面。"}, {"type": "paragraph", "text": "第51分鐘，台電繼續進攻，涂紹捷左腳抽射，台中磐石門將蔡宇翔及時擋出。第58分鐘，楊赫強在禁區邊緣混戰中找到空隙為賴維送出助攻，後者右腳破門，台電將比分擴大至2比0。"}, {"type": "paragraph", "text": "第72分鐘，台中磐石透過長傳發動反擊，山內大空頭球回傳找到劉建緯，後者搶點頭球破門，將比分追近至1比2，令台中磐石燃起希望。"}, {"type": "paragraph", "text": "全力拼戰的台中磐石進入傷停補時第4分鐘，長傳球送入禁區，山內大空控球後失去重心，射門偏離目標，眼看追平機會就此溜走。然而第96分鐘，替補登場的施靖堂從左路傳中至後點，林偉傑在禁區邊緣大力抽射破門，台中磐石在傷停補時第6分鐘完成追平。"}, {"type": "paragraph", "text": "第100分鐘，台中磐石把握最後角球機會強攻，禁區內混戰卻未能把握逆轉良機，最終雙方以2比2握手言和。"}, {"type": "paragraph", "text": "先發陣容 : 4 蔡俊昇 5 周宇杰 9 劉建緯 10 張恒 12 李毓霖 35 李鴻均 37 梁顥騰44 山內大空 48 王義友(C) 66 曾畇浩 99 蔡宇翔 替補 : 1 黃懷賢 2 鄭凱議 6 孫恩祈 7 龔致宇 16 魏志荃 19 周宇豪 21 古傑安 27 施靖堂 32 柯岳廷 47 高冠宇77 林偉傑 88 廖奕盛"}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2026-04-27-match-007' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "2026/04/23 迎風足球場"}, {"type": "paragraph", "text": "乙級聯賽 Week 12 ：桃園國際 1-1 台中磐石預備隊"}, {"type": "paragraph", "text": "進球："}, {"type": "paragraph", "text": "羅獅誠 73’ (桃園)"}, {"type": "paragraph", "text": "江均堯 79’"}, {"type": "paragraph", "text": "4月23日，台灣乙級足球聯賽第12輪賽事，台中磐石預備隊客場面對桃園國際，縱使中途遭到紅牌罰下以十人應戰，仍憑江均堯第79分鐘破門，以1比1逼平對手，帶走一分積分。"}, {"type": "paragraph", "text": "上半場雙方互有攻勢，第31分鐘桃園國際透過自由球進攻，在台中磐石禁區前製造險情。第36分鐘，黃泰奎策動短傳推進，安尚鎮在禁區內傳中，惟隊友未能把握機會。第45分鐘，台中磐石獲得角球機會，陳治瑋嘗試倒掛射門，可惜未能命中目標，雙方以0比0進入中場休息。"}, {"type": "paragraph", "text": "下半場第56分鐘，賽局出現重大變化，台中磐石的許魁在防守中領到本場第二張黃牌，遭裁判罰下場，球隊陷入十人應戰困境。緊接的禁區邊緣自由球，羅獅誠左腳抽射貼著門框而去，未能破門。"}, {"type": "paragraph", "text": "第71分鐘，桃園國際崔圭珉帶球突入禁區遭對手侵犯倒地，裁判當即指向十二碼點球，羅獅誠主罰一蹴而就，桃園國際先馳得點。"}, {"type": "paragraph", "text": "面對一球落後兼少打一人的逆境，台中磐石預備隊並未放棄。第79分鐘，傳中球送至禁區邊緣，許劉鑑鋒停球回傳，替補登場的胡淯翔隨即將球送入禁區，中場江均堯後上抽射破門，為球隊追平比分。"}, {"type": "paragraph", "text": "第87分鐘，桃園國際透過傳中球製造黃金機會，張延安在門前卻未能將球送入網內。賽事終結前台中磐石再獲自由球機會，陳治瑋頭球攻門同樣未能命中。最終比賽以1比1落幕，台中磐石預備隊在艱困情況下帶走一分積分。"}, {"type": "paragraph", "text": "先發陣容 : 3 許魁 8 陳柏穎 13 陳柏崴(C) 14 李偉綸 17 許劉鑑鋒 20 戴彥堯 26 林家樂 28 陳治瑋 29 江均堯 30 陳瑄廷 79 嚴冠侑"}, {"type": "paragraph", "text": "替補 : 15 劉俊佑 18 陳冠智 22 黃昱博 23 盧恩偉 25 薛任祐 33 許紘銘 43 周宇軒 45 胡淯翔"}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2026-04-25-match-008' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "2026/04/19 西屯足球場"}, {"type": "paragraph", "text": "企甲聯賽 Week 16：台中未來 0-1 台中磐石"}, {"type": "paragraph", "text": "進球："}, {"type": "paragraph", "text": "曾畇浩 90''"}, {"type": "paragraph", "text": "第16週台灣企業甲級足球聯賽，19日於西屯足球場上演「台中德比」，台中磐石憑曾畇浩頭球，以1比0擊敗台中未來，拿下隊史首場德比勝利。"}, {"type": "paragraph", "text": "台中磐石開場便積極進取，第3分鐘，隊長李鴻均重奪球權後隨即與山內大空完成撞牆配合起腳射門，惟被台中未來門將松井謙彌及時撲出。第22分鐘，張恒把對手的腳下球攔下後，李鴻均短傳找到左路的梁顥騰，後者在禁區邊緣起腳抽射，可惜皮球貼著門柱出界。第26分鐘，兩人互換角色，梁顥騰帶球推進至禁區邊緣後右腳傳中，李鴻均後上飛身攻門，惟再度未能把握機會。第31分鐘，台中未來亦製造威脅，陳庭揚長傳策動進攻，齋藤遼太以腳背抽射，足球擊中門柱彈出。"}, {"type": "paragraph", "text": "下半場台中未來展開反撲，第47分鐘，陳泓維傳中送至齋藤遼太頭前，後者衝頂力道十足，惟台中磐石門將蔡宇翔飛身將球撲出底線。隨後角球機會，櫻內渚在禁區內壓住一眾後衛搶點頭球攻門，蔡宇翔再度在門線上及時化解。比賽中段節奏趨緩，台中磐石接連換人調整陣容，期望為賽局帶來變化。等待終於在第89分鐘到來，替補上場的周宇杰開出自由球，後衛曾畇浩搶在松井謙彌封阻前頭槌破門，絕殺台中未來。"}, {"type": "paragraph", "text": "台中磐石以1比0拿下第3回「台中德比」勝利，同時也是球團史上首場德比告捷。"}, {"type": "paragraph", "text": "先發陣容 : 4 蔡俊昇 6 孫恩祈 7 龔致宇 10 張恒 12 李毓霖 32 柯岳廷 35 李鴻均 37 梁顥騰 44 山內大空 66 曾昀浩 99 蔡宇翔 替補 : 1 黃懷賢 2 鄭凱議 5 周宇杰 9 劉建緯 16 魏志荃 19 周宇豪 21 古傑安 27 施靖堂 47 高冠宇 77 林偉傑 88 廖奕盛"}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2026-04-19-match-009' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "2026/04/18 西屯足球場"}, {"type": "paragraph", "text": "乙級聯賽 Week 11 ：台中磐石預備隊 4-1 灣島"}, {"type": "paragraph", "text": "進球："}, {"type": "paragraph", "text": "陳治瑋 18’ 28’"}, {"type": "paragraph", "text": "王松甫 39’ (灣島)"}, {"type": "paragraph", "text": "許劉鑑鋒 64’"}, {"type": "paragraph", "text": "許𣁽 88’"}, {"type": "paragraph", "text": "4月18日，台灣乙級足球聯賽第11週於西屯足球場進行，台中磐石預備隊以4：1拿下灣島，主場三分收入囊中。"}, {"type": "paragraph", "text": "第18分鐘，江均堯與隊友完成撞牆配合後，以一記精準穿越球送入禁區，陳治瑋後發先至，以挑射方式將球送進網內，台中磐石預備隊率先取得領先。第28分鐘，台中磐石自由球吊入禁區，灣島後衛頭球解圍不遠，陳治瑋在無人盯防情況下右腳勁射破門，將優勢擴大至2：0。然而第29分鐘，灣島把握薛任祐控球失誤，王松甫單刀破門得分，以2：1進入中場休息。"}, {"type": "paragraph", "text": "比賽第55分鐘，灣島的自由球在台中磐石禁區前製造險情，所幸最後一腳射門偏出門框。第57分鐘，江均堯奪回球權後橫傳，李偉綸在禁區邊緣晃過對手後右腳抽射，惟被灣島門將單手撲出底線。"}, {"type": "paragraph", "text": "第64分鐘，李偉綸帶球突入禁區遭對手侵犯倒地，裁判馬上判罰十二碼罰球，許劉鑑鋒射向右上角，一蹴而就，台中磐石重新拉開比分至3：1。"}, {"type": "paragraph", "text": "第82分鐘，陳治瑋接應長傳球，搶在灣島門將出擊前於禁區邊緣頭球攻門，惟灣島後衛在球門線前解圍。第87分鐘，蔣汯家開出角球，足球劃出弧線越過門將控制範圍，許𣁽在門前頭球得分，鎖定4比1終局比分。"}, {"type": "paragraph", "text": "先發陣容 : 2 鄭凱議 13 陳柏崴(C) 14 李偉綸 17 許劉鑑鋒 19 周宇豪 25 薛任祐 26 林家樂 28 陳治瑋 29 江均堯 30 陳瑄廷 79 嚴冠侑"}, {"type": "paragraph", "text": "替補 : 3 許魁, 8 陳柏穎, 15 劉俊佑, 18 陳冠智, 20戴彥堯, 22 黃昱博 23 盧恩偉, 34 蔣汯家, 39 王宏宇, 40 林政睿, 42 曾偉亘, 43 周宇軒, 51 陳牧恩"}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2026-04-18-match-010' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "2026/04/12 西屯足球場"}, {"type": "paragraph", "text": "企甲聯賽 Week 15：新北航源 0-2 台中磐石"}, {"type": "paragraph", "text": "進球："}, {"type": "paragraph", "text": "黃畯璘 OG 6''"}, {"type": "paragraph", "text": "李鴻均 45+1''"}, {"type": "paragraph", "text": "4月12日，企業甲級足球聯賽第15週賽事，台中磐石在客場以2：0擊敗榜首球隊新北航源，拿下寶貴的3分積分。"}, {"type": "paragraph", "text": "比賽開場僅6分鐘，台中磐石便率先取得領先。山內大空突破防線後在邊路傳中，新北航源後防應對失誤，黃畯璘不慎將球踢入自家球門，令台中磐石得以領先。落後的新北航源隨即展開反撲，連續取得數次角球機會施壓，惟台中磐石防守穩健，一一化解。第33分鐘，新北航源透過快速推進製造機會，是枝真伍的穿越球找到林宗宏，然而台中磐石隊長王義友及時飛身封阻，將射門擋出底線，守住球門。上半場補時階段，李鴻均在禁區內突破羅偉後迅速起腳，皮球穿過門將亞歐都的腳下滾進網內，台中磐石以2：0的優勢步入中場休息。"}, {"type": "paragraph", "text": "下半場第67分鐘，新北航源林宗宏的穿越球為林海正創造射門空間，惟台中磐石守門員蔡宇翔及時飛撲，將威脅化解。第80分鐘，金子尚樹在右路送出傳中，立岩玄輝趕至卻慢了半步，錯失近距離得分機會。面對新北航源的持續施壓，台中磐石穩守防線之餘，亦積極把握反擊時機。第82分鐘，孫恩祈與山內大空連線推進，將球轉移至施靖堂腳下，他在底線前回傳李鴻均，後者第一時間起腳抽射，新北航源後衛黃永竣疑似以手將球擋出底線，惟裁判未有判罰。"}, {"type": "paragraph", "text": "最終，台中磐石全隊堅守崗位，客場以2比0完勝積分榜榜首的新北航源，取下聯賽寶貴的三分積分。"}, {"type": "paragraph", "text": "先發陣容 : 4 蔡俊昇 6 孫恩祈 9 劉建緯 10 張恒 12 李毓霖 35 李鴻均 37 梁顥騰 44 山內大空 48王義友(C) 66 曾畇浩 99 蔡宇翔 GK 替補 : 1 黃懷賢 7 龔致宇 19 周宇豪 21 古傑安 27 施靖堂 77 林偉傑"}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2026-04-12-match-011' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "2026/04/11 西屯足球場"}, {"type": "paragraph", "text": "乙級聯賽 Week 10 ：高雄先鋒 4-1 台中磐石預備隊"}, {"type": "paragraph", "text": "進球："}, {"type": "paragraph", "text": "周浩 44’ 45’ (高雄)"}, {"type": "paragraph", "text": "Bautista 50’ (高雄)"}, {"type": "paragraph", "text": "嚴冠侑 66‘"}, {"type": "paragraph", "text": "黃朝忠 88’ (高雄)"}, {"type": "paragraph", "text": "4月11日，台灣乙級足球聯賽第10週於高雄市立楠梓足球場進行，台中磐石預備隊以1比4不敵高雄先鋒，未能帶走分數。"}, {"type": "paragraph", "text": "高雄先鋒在第23分鐘透過前場短傳配合撕裂對手防線，將球送入網內，惟裁判判定進攻方球員事先越位，進球不予承認。因應當日高溫天氣，賽事依規於上下半場各第30分鐘設置補水時間。上半場末段，台中磐石預備隊連續出現失誤，讓高雄先鋒得以把握機會。第44分鐘，周浩成功搶斷後單刀直入，冷靜破門，率先為主隊取得領先。僅隔一分鐘，他再度抓住對手後防出球遲緩的漏洞，再下一城，在哨響前將比分擴大至2：0。"}, {"type": "paragraph", "text": "下半場第5分鐘，高雄先鋒獲得自由球機會，Junell Bautista接應隊友頭球回傳，禁區內近距離推射建功，擴大比數至3：0。面對三球落後，台中磐石預備隊並未放棄，持續向對手球門施壓，第63分鐘鄭凱議接傳中球的頭球攻門，製造出威脅，但是未能得分。第66分鐘，替補上場的江均堯開出角球，嚴冠侑搶點頭槌破門，射入個人在台中磐石後的首顆進球，將比分拉近至1：3。"}, {"type": "paragraph", "text": "台中磐石追回一球後繼續進攻，第69分鐘許劉鑑鋒接應江均堯的穿越球後起腳射門，惟未能得手。補水時間過後第5分鐘，江均堯再以遠射試門，同樣無功而返。儘管台中磐石在下半場多次換人調度，仍未能改變比賽走向。第88分鐘，台中磐石後場球員跌倒失位，高雄先鋒的黃朝忠趁機單刀破門，最終以4：1鎖定勝局。"}, {"type": "paragraph", "text": "先發陣容 : 2 鄭凱議 3 許魁 8 陳柏穎 14 李偉綸 17 許劉鑑鋒 22 黄昱博(C) 23 盧恩偉 28 陳治瑋 30 陳瑄廷 GK 32柯岳廷 79 嚴冠侑"}, {"type": "paragraph", "text": "替補 : 15 劉俊佑 18 陳冠智 19周宇豪 26 林家樂 27 施靖堂 29 江均堯 33 許紘銘 34 蔣汯家 39 王宏宇 43 周宇軒 45 胡淯翔 51 陳牧恩"}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2026-04-11-match-012' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "2026/03/21 西屯足球場"}, {"type": "paragraph", "text": "乙級聯賽 Week 9：台中磐石預備隊 5-2 新北航源輔大"}, {"type": "paragraph", "text": "進球："}, {"type": "paragraph", "text": "江均堯 12‘"}, {"type": "paragraph", "text": "鄭凱議 (許劉鑑鋒) 41’"}, {"type": "paragraph", "text": "鄭凱議 (李偉綸) 58’"}, {"type": "paragraph", "text": "施靖堂 (戴彥堯) 60‘"}, {"type": "paragraph", "text": "鄭凱議 90+2’"}, {"type": "paragraph", "text": "3月21日，台灣乙級足球聯賽第9週於西屯足球場進行，台中磐石預備隊以5 比2擊敗新北航源輔大，順利收下三分。"}, {"type": "paragraph", "text": "比賽一開始台中磐石即展現強烈進攻企圖，開賽不到1分鐘就完成首次射門施壓。第 12分鐘，球隊在禁區邊緣獲得自由球機會，由江均堯直接破門，先馳得點。第13分鐘許劉鑑鋒接獲穿越球形成單刀，可惜未能把握。第16分鐘右路傳中製造威脅，鄭凱議門前錯失良機。直到第41分鐘，鄭凱議接應許劉鑑鋒的穿越球單刀破門，幫助球隊將比分擴大為2：0，帶著領先優勢進入中場。"}, {"type": "paragraph", "text": "下半場展開不久，第49分鐘盧恩偉成功得對手腳下球後帶球突破至禁區射門，惜中門柱彈出。第53分鐘利用其速度鄭凱議右路突破傳中，許劉鑑鋒頭球攻門未能命中。第57分鐘，新北航源輔大的角球機會，張文翔在混亂中左腳抽射破門，將比分追近至 2：1。不過台中磐石隨即在第58分鐘作出回應，替補上場的李偉綸送出精準穿越球，鄭凱議冷靜完成射門再度擴大領先。"}, {"type": "paragraph", "text": "2分鐘之後，台中磐石再度發動快速短傳配合，戴彥堯穿越球送進禁區，施靖堂左腳破門，將比分拉開至4 ：1。第71分鐘，台中磐石後衛黃昱博在禁區內犯規，送給對手十二碼罰球，但守門員陳瑄廷成功預判對手的射門方向，將球擋出，守住領先優勢。第82分鐘新北航源輔大成功抓到台中磐石防線的漏洞，由江柏鋐單刀破門，形成4：2較接近比數。補時第2分鐘，鄭凱議在禁區邊緣偷得對手腳下球再完成射門，為球隊錦上添花並完成帽子戲法。最終，台中磐石預備隊以5：2擊敗新北航源輔大，在主場拿下關鍵三分。"}, {"type": "paragraph", "text": "先發陣容 : 2 鄭凱議, 13 陳柏崴(C), 17 許劉鑑鋒, 19, 周宇豪, 20 戴彥堯, 22 黄昱博, 23 盧恩偉, 28 陳治瑋, 29 江均堯, 30 陳瑄廷, 32 柯岳廷"}, {"type": "paragraph", "text": "替補 : 1 何乾愷 , 8 陳柏穎, 14 李偉綸, 15 劉俊佑, 18 陳冠智, 25 薛任佑, 26 林家樂, 27施靖堂, 31 汪法華, 34 蔣汯家, 39 王宏宇, 42 曾偉亘, 45 胡淯翔 , 51 陳牧恩, 79 顏冠侑, 98 潘彥宏"}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2026-03-22-match-013' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "2026/03/08 西屯足球場"}, {"type": "paragraph", "text": "企甲聯賽 Week 14：台中磐石 1-1 銘傳大學"}, {"type": "paragraph", "text": "3月8日進行的企業甲級足球聯賽第14週賽事，台中磐石主場迎戰銘傳大學，雙方激戰90分鐘後以1比1握手言和。"}, {"type": "paragraph", "text": "開賽初段銘傳大學率先製造威脅。第13分鐘，銘傳以長傳發動攻勢，前鋒許又仁在禁區邊緣停球後起腳射門，但力道不足，被守門員蔡宇翔穩穩沒收。第16分鐘銘傳大學獲得右路角球機會，馬蒂亞斯將球送入禁區造成門前混戰，許又仁把握機會近距離破門，幫助銘傳大學取得1比0領先。"}, {"type": "paragraph", "text": "落後的台中磐石隨即展開反攻。第24分鐘張恒在中場成功攔截後送出穿越球，劉建緯禁區內左腳抽射，但角度較小未能破門。第39分鐘台中磐石在禁區前獲得自由球機會，周宇杰左腳直接攻門，可惜球稍稍高出。"}, {"type": "paragraph", "text": "下半場的第6分鐘，台中磐石追平比分。一次由後場發起的進攻，魏志荃以短傳組織起攻勢，球隊經過連續7腳傳遞順利推進到前場，周宇杰右路傳中找到門前的劉建緯，後者把握機會破門得手，將比分扳成1：1。"}, {"type": "paragraph", "text": "第67分鐘銘傳大學再度出現破門機會，吳倍希送出直塞球，許又仁獲得單刀機會，但射門被蔡宇翔成功撲救。比賽最後階段台中磐石持續壓上尋求致勝進球，但始終未能再度攻破對手球門。終場雙方以1：1 平手，各自帶走1分積分。"}, {"type": "paragraph", "text": "先發陣容 : 5 周宇杰 9 劉建緯 10 張恒 16 魏志荃 19 周宇豪 32 柯岳廷 37 梁顥騰 44 山內大空 48 王義友 66 曾昀浩 99 蔡宇翔 替補 : 1 黃懷賢 2 鄭凱議 4 蔡俊昇 6 孫恩祈 7 龔致宇 12 李毓霖 21 古傑安 27 施靖堂 30 陳瑄廷 35 李鴻均 47 高冠宇 77 林偉傑 88 廖奕盛"}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2026-03-09-match-014' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "2026/03/01 西屯足球場"}, {"type": "paragraph", "text": "企甲聯賽 Week 13：台中磐石 3-1 陽信北競"}, {"type": "paragraph", "text": "3月1日，第13週企業甲級足球聯賽，台中磐石迎戰陽信北競，靠著上、下半場各有進球演出，最終以3比1擊敗對手，順利收下三分。"}, {"type": "paragraph", "text": "開賽第8分鐘，台中磐石率先打破僵局，周宇杰後場長傳精準找到前場空檔，劉建緯直接起腳破門，助隊取得1比0領先。然而第13分鐘陽信北競把握一次門前混戰機會，由黃偉傑射門得手，迅速將比分扳平。"}, {"type": "paragraph", "text": "隨後台中磐石持續掌握進攻節奏，第26分鐘周宇杰與劉建緯再度完成配合，但劉建緯禁區內射門遭對方門將擋出。第32分鐘台中磐石接連創造攻勢，劉建緯與高冠宇皆獲得射門機會，可惜未能轉化為進球。直到第37分鐘，李毓霖左路送出傳中，山內大空門前頭槌破門，幫助台中磐石再度超前，上半場以2比1領先。"}, {"type": "paragraph", "text": "下半場第56分鐘，陽信北競一度攻至門前形成威脅，所幸門將蔡宇翔及時封堵化解危機。比賽進入中段後，台中磐石透過換人調整節奏，龔致宇、李鴻均、蔡俊昇與張恒陸續替補上陣。"}, {"type": "paragraph", "text": "第72分鐘替補登場不久的李鴻均立即建功，左路傳中精準找到高冠宇，後者以頭槌破門，將比分擴大為3比1，也為球隊奠定勝基。比賽末段陽信北競積極反撲並取得多次角球機會，但台中磐石防線穩定應對，未再失球。最終經過7分鐘補時，台中磐石以3比1擊敗陽信北競，成功拿下關鍵的三分積分。"}, {"type": "paragraph", "text": "先發陣容 : 5 周宇杰 9 劉建緯 12 李毓霖 21 古傑安 27 施靖堂 32 柯岳廷 44 山內大空 47 高冠宇 48 王義友(C) 88 廖奕盛 99 蔡宇翔 替補 : 1 黃懷賢  2 鄭凱議 4 蔡俊昇 6 孫恩祈  7 龔致宇 10 張恒 16魏志荃 19 周宇豪 35 李鴻均 37 梁顥騰 66 曾畇浩 77 林偉傑"}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2026-03-02-match-015' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "為了培養更多具備國際競爭力的台灣球員，台中磐石足球俱樂部持續以開放且務實的態度，積極拓展國際足球視野。繼去年與義甲維羅納（Hellas Verona）建立良好關係後，義大利球隊萊尼亞戈（Legnago Salus）特別於去年11月派遣代表來台，在實地觀摩台乙與企甲聯賽後，親自點名邀請磐石陣中五位優秀球員赴義。本次受邀球員包括高冠宇、李毓霖、許劉鑑鋒、胡淯翔、何乾愷，由技術顧問陳曉明教練率領，於1月25日抵達義大利，展開為期兩週至2月8日的專業隨隊訓練。"}, {"type": "paragraph", "text": "曾於去年赴義丁球隊SSD維加肖訓練並獲得高度評價的高冠宇、本季企甲表現強穩的後衛李毓霖，以及在台乙聯賽嶄露頭角的預備隊前鋒許劉鑑鋒，憑藉賽事突出的表現，獲邀直接進入萊尼亞戈一線隊參與訓練。而隊中擔任台乙聯賽中場胡淯翔與守門員何乾愷，則受邀進入萊尼亞戈U19青訓隊，與當地頂尖青年球員共同磨練職業細節。"}, {"type": "paragraph", "text": "台中磐石表示，非常感謝萊尼亞戈球隊此次的誠摯邀請，讓不同年齡層與特性的球員能分別進入一線隊及青訓體系，精準對接職業層級的訓練需求。這份來自國際職業球會的肯定，對球員而言是極其珍貴的認可，期盼五位球員能珍惜此次海外訓練的機會，將所學經驗轉化為自身養分，為個人職業生涯與台灣足球的未來邁出關鍵一步。"}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2026-02-06-international-016' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "台中磐石攜手Subkarma深耕在地公益　捐贈英語書籍走進潭秀非營利幼兒園 1月12日，台中磐石攜手合作夥伴 Subkarma，前往潭秀國中所屬 「潭秀非營利幼兒園」，捐贈英語幼童學習書籍《Cabbage & Tyler》，透過實際公益行動回饋在地校園，為孩子的成長與學習提供更多支持與陪伴。"}, {"type": "paragraph", "text": "本次捐贈行動，源自Subkarma與台中磐石足球俱樂部的長期合作，讓公益行動得以延伸至幼兒教育現場，展現足球不只是運動，更能串連校園、教育與社會關懷。"}, {"type": "paragraph", "text": "感謝潭秀國中晏傳嫘校長的支持，讓此次公益活動得以順利促成。活動當日，幼兒園園長陳雅雯、台中磐石技術顧問陳曉明，與Subkarma負責人、同時也是《Cabbage & Tyler》作者之一的Anthony也親自到場，四位一同將書籍送到孩子手中。孩子們收到書籍時露出開心的笑容，現場洋溢著溫馨與歡樂的氣氛。"}, {"type": "paragraph", "text": "台中磐石長期深耕基層足球與校園合作，持續以行動實踐社會責任；此次也將公益影響力從球場延伸至課堂，讓孩子從小透過閱讀與英語學習建立語感與自信，為未來發展奠定良好基礎。"}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2026-01-12-community-017' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "2025/12/21 楠梓足球場"}, {"type": "paragraph", "text": "企甲聯賽 Week 12：台中磐石 0-0 南市台鋼 進球：---"}, {"type": "paragraph", "text": "12月21日，台灣企業甲級足球聯賽第十二輪，台中磐石作客楠梓足球場對出戰南市台鋼。雙方全場互有攻守，但均未能攻破對手大門，最終以0比0握手言和，各取1分積分。"}, {"type": "paragraph", "text": "開賽後，台中磐石以穩守反擊為主，成功限制台鋼的進攻節奏，上半場比賽台鋼雖有控球優勢，卻難以製造真正威脅。第35分鐘，台中磐石打出三打三反擊，高冠宇在禁區內與陳威仁發生身體接觸後倒地，但主裁判並未做出任何判決。第39分鐘，南市台鋼由姚克錡與金湘俊在右路短傳配合後傳中，班吉在門前凌空抽射，但直接將球射高，錯失黃金先機。半場雙方零比零收場。"}, {"type": "paragraph", "text": "易邊再戰，第55分鐘，台鋼由高銳左路突破下底傳中，禁區內無人盯防的姚克錡起腳攻門，不過未能命中目標。第67分鐘，台中磐石替補上場的組合帶來火花，山內大空送出穿越球給劉建緯，但被台鋼防守破壞，未能形成射門。第73分鐘，台中磐石右路再度組織攻勢，山內大空切入禁區時遭劉和翰推撞倒地，不過邊裁並未舉旗示意犯規，場上判決維持比賽繼續。第77分鐘，周宇杰成功預判截球後傳球到禁區邊緣，山內大空回傳王義友，後者迎球抽射，但角度稍高偏出。第78分鐘，龔致宇在進攻時於禁區內被劉和翰踢跌，但主裁判並未有任何表示。"}, {"type": "paragraph", "text": "比賽第87分鐘，台鋼中場薩庫兩黃變一紅被罰出場，需要以十人應戰，比賽局勢也開始緊湊。傷停補時六分鐘的裡面，台中磐石在前場連續製造威脅。第92分鐘，施靖堂在禁區前與山內大空配合，後者送出穿越球，可惜劉建緯門前射高。完場前，台中磐石掌握到絕佳的二打一快攻機會，山內大空選擇吊射，但遭潘文傑沒收。"}, {"type": "paragraph", "text": "全場結束，台中磐石與南市台鋼互繳白卷，以0比0握手言和，在楠梓足球場各取1分積分。"}, {"type": "paragraph", "text": "先發陣容 : 1 黃懷賢 5 周宇杰 6 孫恩祈 12 李毓霖16 魏志荃21 古傑安 35 李鴻均(C) 47 高冠宇 48 王義友 88 廖奕盛 97 林駿凱"}, {"type": "paragraph", "text": "替補 : 1 黃懷賢 2 鄭凱議 3 許魁 4 蔡俊昇 6孫恩祈 9 劉建緯 19 周宇豪 27 施靖堂 30 陳瑄廷, 32 柯岳廷, 35 李鴻均, 37 梁顥騰 66 曾畇浩 77 林偉傑 97 林駿凱"}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2025-12-22-match-018' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "2025/12/14 西屯足球場"}, {"type": "paragraph", "text": "企甲聯賽 Week 11：台中磐石 0-1 大同足球隊 進球："}, {"type": "paragraph", "text": "游家煌 58'' (大同)"}, {"type": "paragraph", "text": "第十一輪企甲聯賽賽事，台中磐石與大同足球隊形成拉鋸，並於下半場創造多次具威脅的得分機會，可惜臨門一腳欠缺準度，加上防線一次判斷失誤遭到對手把握，最終以0比1惜敗大同，未能收下積分。"}, {"type": "paragraph", "text": "比賽第13分鐘，台中磐石發動首次具威脅的進攻，山內大空在前場成功反搶後與高冠宇進行配合，隨後橫傳至禁區邊緣，可惜楊朝景後續的射門未能命中。"}, {"type": "paragraph", "text": "第34分鐘，大同把握台中磐石未能即時解圍的機會，深澤佑之典在禁區邊緣嘗試遠射，不過台中磐石守門員蔡宇翔站位良好，成功將球擋出。上半場雙方互有攻守，但均未能破門，以0比0進入中場休息。"}, {"type": "paragraph", "text": "下半場第52分鐘，大同未能將台中磐石的自由球完全解圍，周宇杰把握機會左腳遠射，迫使守門員東風淳飛身撲救，隨後施靖堂跟進補射，可惜稍稍偏出。第54分鐘，台中磐石再度獲得禁區邊緣的自由球機會，魏志荃主罰直接射門，足球僅以些微差距偏離目標。"}, {"type": "paragraph", "text": "錯失破門良機後，第58分鐘大同隨即給予回應，右路傳中吊入禁區，台中磐石防守判斷出現失誤，讓游家煌頭球破門，打進全場唯一進球。"}, {"type": "paragraph", "text": "第73分鐘，台中磐石仍積極尋求追平機會，高冠宇送出精妙穿越球，山內大空下底傳中，魏志荃門前搶點抽射，可惜未能命中目標，再度錯失扳平良機。"}, {"type": "paragraph", "text": "補時5分鐘內，台中磐石全力反撲仍未能改寫比分，最終以0比1不敵大同足球隊。"}, {"type": "paragraph", "text": "先發陣容 : 5 周宇杰 7 龔致宇 11 楊朝景 12 李毓霖 16 魏志荃 21 古傑安 44 山內大空 47 高冠宇 48 王義友(C) 88 廖奕盛 99 蔡宇翔"}, {"type": "paragraph", "text": "替補 : 1 黃懷賢 2 鄭凱議 3 許魁 4 蔡俊昇 6孫恩祈 9 劉建緯 19 周宇豪 27 施靖堂 30 陳瑄廷, 32 柯岳廷, 35 李鴻均, 37 梁顥騰 66 曾畇浩 77 林偉傑 97 林駿凱"}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2025-12-14-match-019' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "2025/12/13 西屯足球場"}, {"type": "paragraph", "text": "乙級聯賽 Week 7：台中磐石預備隊 1-3 高雄先鋒"}, {"type": "paragraph", "text": "進球："}, {"type": "paragraph", "text": "陳治瑋 70'' 乙級聯賽第一循環最後一場賽事，台中磐石預備隊主場迎戰高雄先鋒，儘管下半場一度扳回一城並持續嘗試反攻，但開賽階段失球過快，最終仍以1比3不敵對手。"}, {"type": "paragraph", "text": "比賽第12分鐘，高雄先鋒由左路發動攻勢，連續以傳中製造威脅，儘管台中磐石預備隊守門員陳冠智與後防線接連擋下三次射門，但第四波攻勢仍遭盧安安德森把握機會破門，高雄先鋒先馳得點。"}, {"type": "paragraph", "text": "第23分鐘，台中磐石預備隊在禁區邊緣獲得自由球機會，由江均堯操刀主罰，可惜射門稍稍偏出。第26分鐘，高雄先鋒再度由左路傳中製造威脅，歐塔斐門前把握機會破門，將比分擴大為2比0。"}, {"type": "paragraph", "text": "第35分鐘，台中磐石預備隊積極反撲，張恒帶球突破後嘗試遠射，角度與力度俱佳，但遭對方守門員飛身撲出。第37分鐘後，戴彥堯左路傳中，李偉綸背身拿球再傳給張恒，後者起腳抽射，足球先被守門員擋到再擊中門柱彈出，與進球僅一步之遙。半場結束，高雄先鋒以2比0領先。"}, {"type": "paragraph", "text": "第49分鐘，高雄先鋒由歐塔斐送出穿越球，助攻芝康太朗破門，比分改寫為3比0。第68分鐘，台中磐石預備隊獲得自由球機會，戴彥堯直接射門命中目標，可惜遭守門員以雙拳擊出。"}, {"type": "paragraph", "text": "第70分鐘，台中磐石預備隊的短傳配合之後，江均堯在左路底線前精準傳中，陳治瑋擺脫防守後起腳破門，將比分追成1比3。第72分鐘，高雄先鋒製造單刀機會，不過陳冠智臨危不亂成功出迎封阻，力保球門不再失守。"}, {"type": "paragraph", "text": "最終，台中磐石預備隊在西屯主場以1比3不敵高雄先鋒，未能把握主場搶分。"}, {"type": "paragraph", "text": "先發陣容 : 10 張恒 13 陳柏崴(C) 14 李偉綸 17 許劉鑑鋒 18 陳冠智 20 戴彥堯 22 黄昱博 23 盧恩偉 25 薛任祐 28 陳治瑋 29 江均堯"}, {"type": "paragraph", "text": "替補 : 1 何乾愷 8 陳柏穎 15 劉俊佑 26 林家樂 39 王宏宇 40 林政睿 45 胡淯翔 98 潘彥宏"}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2025-12-14-match-020' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "2025/12/06 西屯足球場"}, {"type": "paragraph", "text": "乙級聯賽 Week 6：台中磐石足球預備隊 3-3 陽信台北競技預備隊"}, {"type": "paragraph", "text": "進球："}, {"type": "paragraph", "text": "許劉鑑鋒 4'' 29''"}, {"type": "paragraph", "text": "戴彥堯 70'' 12月6日，第六輪乙級聯賽第六輪，台中磐石預備隊開局順利、許劉鑑鋒梅開二度，下半場一度取得兩球領先優勢，但之後時間後防連續失誤，最終遭陽信北競預備隊追平，雙方以3比3收場，台中磐石預備隊遺憾無緣全取三分。"}, {"type": "paragraph", "text": "比賽剛開場僅3分鐘，台中磐石預備隊在中場成功斷球隨即展開反擊，江均堯送出精準穿越球，許劉鑑鋒冷靜推射破門，先馳得點。不過不到一分鐘後，陽信北競預備隊立即以長傳施壓，迫使台中磐石守門員出擊迎球失誤，面對空門將比分追成1:1。第29分鐘，陽信北競預備隊守門員失誤，球直接落到許劉鑑鋒腳下，讓他梅開二度，台中磐石預備隊帶著2:1領先結束上半場。"}, {"type": "paragraph", "text": "第71分鐘，台中磐石預備隊發動快速反擊，左路傳中送到門前，戴彥堯近距離抽射得手，將比分擴大至3:1。然而第73與82分鐘，後防連續出現錯誤，被對手兩度破門，比分再度回到原點。第86分鐘，許劉鑑鋒接應穿越球突入禁區，晃過防守後起腳，可惜稍稍偏出，錯過再次領先的黃金機會。第91分鐘，台中磐石預備隊獲得禁區邊緣自由球，張恒主罰未能命中目標。"}, {"type": "paragraph", "text": "最終，台中磐石預備隊以3比3戰平陽信北競預備隊，錯失全取三分積分的機會。"}, {"type": "paragraph", "text": "先發陣容 : 10 張恒 13 陳柏崴(C) 15 劉俊佑 17 許劉鑑鋒 20 戴彥堯 22 黄昱博 23 盧恩偉 25 薛任祐 28 陳治瑋 29 江均堯 39 王宏宇"}, {"type": "paragraph", "text": "替補 : 1 何乾愷 8 陳柏穎 14 李偉綸 8 陳冠智 26 林家樂 40 林政睿 45 胡淯翔 98 潘彥宏"}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2025-12-09-match-021' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "2025/12/07 西屯足球場"}, {"type": "paragraph", "text": "企甲聯賽 Week 10：台灣電力 1-2 台中磐石 進球："}, {"type": "paragraph", "text": "高偉傑 11'' (台電)"}, {"type": "paragraph", "text": "山內大空 18’"}, {"type": "paragraph", "text": "李毓霖 27’"}, {"type": "paragraph", "text": "12月7日，企甲聯賽本週續戰，台中磐石作客面對老牌球隊台電，在先失一球的情況下迅速調整，比賽中段上演逆轉戲碼，最終以2比1力克對手，成功帶走關鍵3分。"}, {"type": "paragraph", "text": "比賽一開始節奏相當明快。第11分鐘，台電在禁區邊緣的自由球射門雖然打在人牆上但形成二次進攻，高偉傑抓住反彈球直接抽射破門，為台電先馳得點。落後的台中磐石很快做出回應。第18分鐘，前鋒山內大空個人能力再度發揮，他帶球突破後傳球，這次傳球雖然沒有成功送到隊友腳下，但反彈球再度落到山內大空面前，他隨即冷靜射門，足球貼地鑽進球門左側，將比分扳平1比1。"}, {"type": "paragraph", "text": "比賽節奏持續高漲。第20分鐘，高偉傑接應右路傳中再次獲得起腳機會，但這次射門擊中橫樑彈出。第27分鐘，台中磐石打出精彩長傳進攻，魏志荃左腳送出精準長傳吊入禁區，李毓霖力壓防守球員抽射破門，幫助台磐石完成逆轉，2比1領先。"}, {"type": "paragraph", "text": "下半場，台電加強反攻，第49分鐘利用長傳製造威脅，楊晨穎在禁區內抽射，但守門員蔡宇翔反應迅速將球擋出。比賽後段台中磐石還有多次擴大比分的機會。第71分鐘，替補上陣的楊朝景右路突破後傳中，高冠宇門前抽射但遭後衛擋下。第80分鐘，台中磐石在左路自由球機會中再度創造威脅，楊朝景高高躍起頭槌攻門，球僅差一步偏出。"}, {"type": "paragraph", "text": "補時階段台電全力反撲，第96分鐘的頭槌攻門也未能越過蔡宇翔把守的球門，使比賽最終以2比1作收。台中磐石成功拿下本季第三場勝利，在聯賽積分榜上再添重要3分積分。"}, {"type": "paragraph", "text": "先發陣容 : 5 周宇杰 9 劉建緯 12 李毓霖 16 魏志荃 21 古傑安 37 梁顥騰 44 山內大空 48 王義友(C) 88 廖奕盛 97 林駿凱 99 蔡宇翔"}, {"type": "paragraph", "text": "替補 : 1 黃懷賢 2 鄭凱議 3 許魁  4 蔡俊昇 6 孫恩祈 7 龔致宇 11 楊朝景 19 周宇豪"}, {"type": "paragraph", "text": "27 施靖堂 30 陳瑄廷 32 柯岳廷 35 李鴻均 47 高冠宇 66 曾畇浩 77 林偉傑"}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2025-12-07-match-022' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "2025/11/30 西屯足球場"}, {"type": "paragraph", "text": "企甲聯賽 Week 9：台中FUTURO 4-0 台中磐石 進球："}, {"type": "paragraph", "text": "齋藤遼太42'' 65''"}, {"type": "paragraph", "text": "陳泓維 64''"}, {"type": "paragraph", "text": "程昊79''"}, {"type": "paragraph", "text": "11月30日，台中磐石在西屯足球場對上同城的台中未來。台中磐石雖然創造多次具威脅的進攻，但在關鍵時刻欠缺臨門一腳，最終以0比4落敗，無緣在德比戰中搶下積分。"}, {"type": "paragraph", "text": "比賽進入第30分鐘後節奏逐漸加快，台中未來率先由李茂在禁區外轟門，所幸守門員黃懷賢反應迅速，穩穩將球抱住。第42分鐘，台中未來右路傳中造成門前混亂，台中磐石防線未能及時解圍，齋藤遼太抓準機會左腳破門，台中磐石半場以0比1落後。"}, {"type": "paragraph", "text": "易邊再戰後台中磐石積極尋求反攻。第55分鐘，前鋒劉建緯在禁區邊緣轉身抽射，可惜角度過正被門將沒收。第60分鐘，魏志荃從右路送出精準傳中，劉建緯力壓對手頭槌攻門，只差一步偏出，與追平進球擦身而過。"}, {"type": "paragraph", "text": "未能把握追平良機後，台中磐石在第64與第66分鐘連續遭到對手突破，比分被拉開到3-0。第77分鐘，台中磐石在角球攻勢中由山內大空將球送入球門，但裁判示意越位在先，進球無效。第79分鐘，台中未來再以長傳穿越防線，由程昊破門，將比分鎖定在4比0。"}, {"type": "paragraph", "text": "此役雖然吞下敗戰，但台中磐石全隊將持續調整攻守細節，力拚在接下來的賽程中找回最佳節奏，爭取在下一輪企甲聯賽反彈。"}, {"type": "paragraph", "text": "先發陣容 : 1 黃懷賢 2 鄭凱議 4 蔡俊昇 9 劉建緯 12 李毓霖 32 柯岳廷 35 李鴻均 (C) 44 山內大空 48 王義友 88 廖奕盛 98 林駿凱"}, {"type": "paragraph", "text": "替補 : 3 許魁, 5周宇杰, 6孫恩祈, 7 龔致宇, 11楊朝景, 16魏志荃,19 周宇豪, 21 古傑安, 27 施靖堂, 30 陳瑄廷, 37 梁顥騰 , 47 高冠宇, 66 曾畇浩, 77 林偉傑, 99 蔡宇翔"}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2025-12-01-match-023' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "2025/11/22 迎風足球場"}, {"type": "paragraph", "text": "乙級聯賽 Week 5：銘傳大學Desafio 1-3 台中磐石足預備隊"}, {"type": "paragraph", "text": "進球："}, {"type": "paragraph", "text": "李偉綸 68’"}, {"type": "paragraph", "text": "許劉鑑鋒 74’ 80'' 台中磐石預備隊在本輪乙級聯賽上演精彩逆轉秀，以3比1擊敗銘傳Desafio，成功拿下關鍵3分"}, {"type": "paragraph", "text": "。"}, {"type": "paragraph", "text": "比賽第38分鐘，許劉鑑鋒在底線前積極反搶成功後送出傳中，江均堯於禁區前跟進抽射，但被對手後衛擋走。隨後連續兩次角球攻勢，張恒在禁區邊緣找到空檔起腳，可惜未能命中目標。"}, {"type": "paragraph", "text": "易邊之後，第53分鐘Desafio把握角球機會率先破門。第61分鐘，台中磐石預備隊在禁區前獲得自由球機會，張恒主罰直接射門，雖然角度精準，但仍被Desafio守門員撲住。"}, {"type": "paragraph", "text": "不過台中磐石預備隊並未氣餒，隨後在12分鐘內連進三球，完成漂亮逆轉。"}, {"type": "paragraph", "text": "第68分鐘，李偉綸接應許劉鑑鋒的精準穿越球，形成單刀冷靜破門，追成1-1。第74分鐘，李偉綸在禁區內接獲長傳凌空抽射，對方門將雖然拍出，但許劉鑑鋒門前補射得手，助球隊反超。第80分鐘，台中磐石預備隊抓住對手傳球失誤，由陳治瑋送出關鍵助攻，許劉鑑鋒冷靜再下一城，將比分鎖定為3比1。"}, {"type": "paragraph", "text": "最終台中磐石預備隊逆轉擊敗銘傳Desafio，收下關鍵3分。"}, {"type": "paragraph", "text": "先發陣容 : 10 張恒 13 陳柏崴(C) 15 劉俊佑 17 許劉鑑鋒 20 戴彥堯 22 黄昱博 23 盧恩偉 25 薛任祐 28 陳治瑋 29  江均堯 39 王宏宇"}, {"type": "paragraph", "text": "替補 : 1 何乾愷 8 陳柏穎 14 李偉綸 18 陳冠智 26 林家樂 40 林政睿 45 胡淯翔 98潘彥宏"}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2025-11-24-match-024' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "2025/11/23 輔仁大學足球場"}, {"type": "paragraph", "text": "企甲聯賽 Week 8：新北航源 3-0 台中磐石 進球："}, {"type": "paragraph", "text": "OG 16'' 是枝真伍 33'' (航源) 王柏穎 56'' (航源)"}, {"type": "paragraph", "text": "台中磐石本場比賽開局不利，第16分鐘出現烏龍球，李鴻均在解圍對手傳中時不慎將球踢進自家球門，讓新北航源先取得領先。第22分鐘，台中磐石獲得角球機會，李鴻均開球後，山內大空前點衝頂攻門，可惜遭到門將撲出。僅隔1分鐘，新北航源也以傳中製造威脅，蔡宇翔及時飛撲將對手的頭槌化解。"}, {"type": "paragraph", "text": "第33分鐘，新北航源的是枝真伍接應傳中頂進一球，比分拉開至2比0。上半場尾聲，山內大空在第40與第42分鐘連續取得射門空檔，但都未能命中。台中磐石半場以兩球落後。"}, {"type": "paragraph", "text": "易邊後，台中磐石在第56分鐘右路防線被突破後，王柏穎在禁區內破門，比分擴大為3比0。第68分鐘，林駿凱主罰禁區邊緣自由球，球路漂亮但稍稍偏出。第80分鐘，鄭凱議右路突破後精準傳中，林駿凱甩開防守抽射卻被守門員擋下。"}, {"type": "paragraph", "text": "全場比賽結束，台中磐石以0比3不敵新北航源，無緣帶走分數。"}, {"type": "paragraph", "text": "先發陣容 : 4 蔡俊昇 5 周宇杰 6 孫恩祈 11 楊朝景 12 李毓霖 35 李鴻均(7) 44 山內大空 47 高冠宇 77 王義友 88 廖奕盛 99 蔡宇翔"}, {"type": "paragraph", "text": "替補 : 1 黃懷賢, 2鄭凱議, 3 許魁, 7 龔致宇, 9 劉建緯, 16魏志荃,19 周宇豪,21 古傑安, 27 施靖堂, 30 陳瑄廷, 32 柯岳廷, 37梁顥騰 , 66曾畇浩, 77林偉傑, 97林駿凱"}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2025-11-24-match-025' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "與義甲維羅納合作邁出第一步 台中磐石球員啟程赴義大利訓練"}, {"type": "paragraph", "text": "台中磐石足球俱樂部持續推動國際足球交流與球員培訓計畫，將會在11月3日安排四名球員前往義大利展開為期一週的訓練，藉此拓展視野、提升技術，並累積高水平國際經驗。"}, {"type": "paragraph", "text": "其中，中場球員 龔致宇 與守門員 何乾愷 將前往義大利甲級球會維羅納（Hellas Verona FC） 參與訓練。透過親身到義甲球隊的訓練與練習賽，學習歐洲頂級聯賽球隊的日常運作和職業球員的工作方式。"}, {"type": "paragraph", "text": "此外，中場 高冠宇 及 李鴻均 則將前往 義大利丁級球隊SSD維加肖（SSD Vigasio） 進行訓練交流，深入了解義大利球隊的運作模式與比賽風格。"}, {"type": "paragraph", "text": "台中磐石足球俱樂部表示，此次義大利訓練計畫是與義甲維羅納簽下合作協議後的第一步，也是球隊長期推動國際化策略的重要一步。除了球員遠赴義大利進行訓練，台中磐石俱樂部的管理層也會到義大利進行一系列考察及交流，期望將聞名於世的義大利防守概念帶回台灣，並且讓台灣足球在國際舞台上被看見。"}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2025-11-04-international-026' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "陳曉明出任台中磐石足球俱樂部技術顧問 助力打造長期發展藍圖"}, {"type": "paragraph", "text": "Inspiring Players 啟發球員"}, {"type": "paragraph", "text": "台中磐石足球俱樂部宣布——陳曉明教練正式出任技術顧問，攜手啟動俱樂部長期發展藍圖。"}, {"type": "paragraph", "text": "陳教練擁有豐富的國際足球經驗與專業知識，未來將協助球隊建立完整的技術體系，從一線隊到青訓架構，全方位推動球隊在企業甲級聯賽及青少年系統的持續成長，啟發球員潛能，激發更多台灣足球新力量。"}, {"type": "paragraph", "text": "Shaping Champions 塑造冠軍"}, {"type": "paragraph", "text": "陳教練將主導俱樂部的長期技術規劃，依據球隊統一的比賽風格與訓練理念，制定系統化的訓練方針與執行計畫。"}, {"type": "paragraph", "text": "隨著曉明教練的加入，台中磐石青訓學院的籌備工作正式邁入新階段，未來將推出長期培訓課程與內部教練養成制度，透過專業教育與持續進修，打造完善的培訓環境與冠軍團隊，讓專業成為球員與教練共同的語言。"}, {"type": "paragraph", "text": "Local Pride 在地驕傲"}, {"type": "paragraph", "text": "台中磐石足球俱樂部自創立以來，始終以深耕台中、培育在地足球人才為使命。"}, {"type": "paragraph", "text": "陳曉明教練深刻理解地方足球文化的重要性。"}, {"type": "paragraph", "text": "他將運用多年亞洲職業足球經驗，協助台中磐石建立與社區更緊密的連結——從青少年訓練到基層推廣，讓專業足球精神在台中扎根成長。"}, {"type": "paragraph", "text": "這份跨越地域的交流，不只是技術的傳承，更是對「讓在地成為榮耀」這份信念的實踐。"}, {"type": "paragraph", "text": "Global Influence 撼動全球"}, {"type": "paragraph", "text": "在國際發展層面，陳教練將運用其海外人脈與專業視野，協助俱樂部拓展全球合作網絡，打造具有國際競爭力的發展模式。"}, {"type": "paragraph", "text": "台中磐石足球俱樂部表示，陳曉明教練的加入是邁向系統化、專業化與國際化的重要一步。"}, {"type": "paragraph", "text": "我們將持續以「啟發球員、塑造冠軍、在地驕傲、撼動全球」為目標，為台灣足球創造更長遠的未來。"}, {"type": "paragraph", "text": "專業資格："}, {"type": "paragraph", "text": "亞洲足協（AFC）專業級教練證（AFC Professional Coaching License／AFC Pro License）"}, {"type": "paragraph", "text": "亞洲足協教練導師資格"}, {"type": "paragraph", "text": "香港足球總會教練導師資格"}, {"type": "paragraph", "text": "亞洲足協精英狀態訓練導師資格"}, {"type": "paragraph", "text": "國際足協（FIFA）草根發展導師資格"}, {"type": "paragraph", "text": "職業足球資歷："}, {"type": "paragraph", "text": "2004–2005：香港08教練"}, {"type": "paragraph", "text": "2005–2006：香港09教練"}, {"type": "paragraph", "text": "2006–2007：和富大埔主教練"}, {"type": "paragraph", "text": "2007–2008：華家堡主教練"}, {"type": "paragraph", "text": "2008：香港代表隊教練"}, {"type": "paragraph", "text": "2008–2009：東方主教練"}, {"type": "paragraph", "text": "2009-10：香港足球總會技術總監"}, {"type": "paragraph", "text": "2010–2012：天水圍飛馬主教練"}, {"type": "paragraph", "text": "2015-2018：澳門足球總會技術總監"}, {"type": "paragraph", "text": "2017–2018：澳門代表隊主教練"}, {"type": "paragraph", "text": "2018–2023：理文足球會主教練"}, {"type": "paragraph", "text": "2023–2025：中華台北女子足球代表隊總教練"}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2025-11-03-club-027' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "2025/11/02 銘傳大學足球場"}, {"type": "paragraph", "text": "企甲聯賽 Week 7：銘傳大學 0-1 台中磐石 進球："}, {"type": "paragraph", "text": "曾畇浩 50’"}, {"type": "paragraph", "text": "比賽進行到第22分鐘，台中磐石獲得自由球機會，周宇杰長傳吊入禁區，銘傳大學後衛解圍不遠，蔡俊昇上前抽射，可惜被防守球員擋下。第30分鐘，銘傳大學利用穿越球製造出單刀機會，但初次於企甲登場的守門員黃懷賢判斷精準，果斷出擊封阻馬蒂亞斯的射門，力保球門不失。上半場雙方互有攻勢，但仍以0比0進入休息。"}, {"type": "paragraph", "text": "下半場第50分鐘，台中磐石取得突破，林駿凱主罰自由球吊入禁區，銘傳大學後防解圍不遠，後衛曾畇浩抓準機會，直接抽射破門，取得重要的領先優勢。第69分鐘，台中磐石在前場斷球後快速反擊，林駿凱左路右腳傳中，替補上場的山內大空高高躍起頭槌攻門，惜稍稍偏出。最終，台中磐石以1比0擊敗銘傳大學，成功拿下俱樂部歷史上的首場零封勝利。"}, {"type": "paragraph", "text": "先發陣容 : 1 黃懷賢 2 鄭凱議 4 蔡俊昇 5 周宇杰(C) 12 李毓霖 16 魏志荃 37 梁顥騰 47 高冠宇"}, {"type": "paragraph", "text": "66 曾畇浩 88 廖奕盛 97林駿凱"}, {"type": "paragraph", "text": "替補 : 3 許魁, 6 孫恩祈,7 龔致宇, 9 劉建緯, 11 楊朝景,19 周宇豪,21 古傑安,27 施靖堂, 30 陳瑄廷, 32 柯岳廷, 35 李鴻均, 44 山內大空, 48 王義友, 77林偉傑, 99 蔡宇翔"}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2025-11-02-match-028' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "2025/11/01 西屯足球場"}, {"type": "paragraph", "text": "乙級聯賽 Week 4：台中磐石預備隊 2:0 桃園國際"}, {"type": "paragraph", "text": "進球："}, {"type": "paragraph", "text": "李偉綸 75’"}, {"type": "paragraph", "text": "張恒 80’"}, {"type": "paragraph", "text": "開賽僅1分鐘，台中磐石率先製造威脅，張恒在禁區邊緣混戰中右腳抽射，迫使桃園國際守門員奮力撲救。第6分鐘，張恒再度從左路突破，禁區內閃過防守後起腳射門，又被門將擋下。第30分鐘，台中磐石發動反擊，中場江均堯送出精準穿越球，許劉鑑鋒形成單刀，可惜挑射偏出。上半場結束，雙方仍互交白卷。"}, {"type": "paragraph", "text": "下半場台中磐石預備隊率先射門，替補登場的李偉綸禁區外抽射可惜偏出。隨後李偉綸右路傳中，戴彥堯飛身鏟射，再度被門將化解。第75分鐘，台中磐石預備隊終於打破僵局，李偉綸在小禁區前將傳中停下轉身，右腳抽射破門，為球隊先馳得點。5分鐘後，張恒中場持球推進後遠射破門，精彩世界波將比分改寫為2:0。"}, {"type": "paragraph", "text": "最終，台中磐石預備隊在主場憑藉穩定表現與關鍵進球，以2比0力退桃園國際，成功收下乙級聯賽二連勝。"}, {"type": "paragraph", "text": "先發陣容 : 10 張恒, 13 陳柏崴 (C), 14 李偉綸, 15 劉俊佑, 18 陳冠智, 20 戴彥堯, 22 黄昱博"}, {"type": "paragraph", "text": "23 盧恩偉, 25 薛任祐, 28 陳治瑋, 45 胡淯翔"}, {"type": "paragraph", "text": "替補 : 14 李偉綸 15 劉俊佑 26 林家樂 39 王宏宇 40 林政睿 45 胡淯翔"}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2025-11-01-match-029' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "2025/10/25 西屯足球場"}, {"type": "paragraph", "text": "乙級聯賽 Week 3：灣島 2:7 台中磐石預備隊"}, {"type": "paragraph", "text": "進球："}, {"type": "paragraph", "text": "張恒 10’"}, {"type": "paragraph", "text": "戴彥堯 14’"}, {"type": "paragraph", "text": "陳治瑋 56’"}, {"type": "paragraph", "text": "許劉鑑鋒 62’ 79’ 83’"}, {"type": "paragraph", "text": "李偉綸 85’"}, {"type": "paragraph", "text": "開賽僅10分鐘，磐石預備隊利用長傳展開攻勢，對方後防未能及時解圍，張恒在禁區內右腳抽射破門，為球隊先馳得點。4分鐘後，戴彥堯接應張恒的穿越球，冷靜射入球門，迅速將比分拉開至2:0。雖然磐石掌握主動權，但灣島在第30分鐘利用穿越球製造單刀機會追回一球。第43分鐘，磐石後場傳球失誤，讓灣島獲得遠射機會，不過被門將陳冠智穩穩沒收。上半場結束，台中磐石預備隊暫時以2:1領先。"}, {"type": "paragraph", "text": "易邊再戰，第56分鐘盧恩偉截下對手失誤後橫傳給陳治瑋，後者冷靜面對門將破門，改寫比數為3:1。第62分鐘，替補上陣的許劉鑑鋒接應隊友傳球，在禁區內巧妙控球後抽射得手，擴大領先為4:1。第71分鐘，灣島球員個人突破成功破門追回一球，但台中磐石預備隊的攻勢並未停歇。第79分鐘，江均堯傳中至禁區邊緣，許劉鑑鋒上前抽射破門，讓比分變成5:2。第83分鐘，李偉綸助攻許劉鑑鋒完成「帽子戲法」，攻入第六球。兩分鐘後，江均堯在底線前傳中，李偉綸搶點頭槌破門，為球隊鎖定勝局。最終，台中磐石預備隊以7:2大勝灣島。"}, {"type": "paragraph", "text": "先發陣容 : 10 張恒, 13 陳柏崴 (C), 14 李偉綸, 15 劉俊佑, 18 陳冠智, 20 戴彥堯, 22 黄昱博"}, {"type": "paragraph", "text": "23 盧恩偉, 25 薛任祐, 28 陳治瑋, 45 胡淯翔"}, {"type": "paragraph", "text": "替補 : 1 何乾愷, 17 許劉鑑鋒, 26 林家樂, 29 江均堯, 39 王宏宇, 40 林政睿, 98 潘彥宏"}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2025-10-26-match-030' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "2025/10/26 輔仁大學足球場"}, {"type": "paragraph", "text": "企甲聯賽 Week 6：陽信北競 2-2 台中磐石 進球："}, {"type": "paragraph", "text": "山內大空 2’ 51’"}, {"type": "paragraph", "text": "台中磐石得到了理想的開局，開賽僅2分鐘，山內大空在禁區內遭對手拉倒，裁判果斷判給12碼，他親自主罰冷靜射向球門右側，為球隊先開紀錄。第11分鐘，台中磐石組織長傳反擊，隊長李鴻均在禁區邊緣巧妙停球後分邊，古傑安跟進抽射，但被陽信北競門將段昍穩穩撲住。第18分鐘，陽信北競獲得自由球機會，由楠山剛志在門前頂進球門，將比分追成1：1。第36分鐘，台中磐石前場壓迫奏效，高冠宇得球後立刻起腳勁射，但再度被段昍擋出底線。第44分鐘，陽信北競後場出現傳球失誤，古傑安機警送出穿越球，山內大空第一時間起腳，可惜稍稍偏出。半場結束，雙方以1比1暫時平手。"}, {"type": "paragraph", "text": "下半場開踢不久，第50分鐘，陽信北競球員在禁區內犯規，台中磐石再度獲得十二碼機會。山內大空再度操刀，冷靜射入球門左側，梅開二度，也讓磐石再度超前比分。第76分鐘，廖奕盛在防守角球時不慎放倒對手，裁判判給陽信北競十二碼，山崎直之主罰命中，雙方再度回到同一起跑線。第89分鐘，陽信北競獲得黃金機會，楠山剛志在禁區內起腳勁射，台中磐石門將蔡宇翔反應迅速，飛身撲救化解危機。進入補時階段第6分鐘，台中磐石發動快速反擊，蔡俊昇在禁區內擺脫防守後起腳射門，可惜被對方球員擋出。最終，台中磐石與陽信北競激戰90分鐘後，以2比2握手言和，各取一分。"}, {"type": "paragraph", "text": "先發陣容 : 4 蔡俊昇, 7 龔致宇, 12 李毓霖, 16 魏志荃, 21 古傑安, 35 李鴻均 (C), 44 山内大空, 47 高冠宇, 66 曾畇浩, 88 廖奕盛, 99 蔡宇翔"}, {"type": "paragraph", "text": "替補 : 1 黃懷賢, 2 鄭凱議, 3 許魁, 5 周宇杰, 6 孫恩祈, 9 劉建緯, 11 楊朝景, 19 周宇豪, 30 陳瑄廷, 32 柯岳廷, 37 梁顥騰, 48 王義友, 97 林駿凱"}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2025-10-26-match-031' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "2025/09/28 臺南市立足球場"}, {"type": "paragraph", "text": "企甲聯賽 Week 5：南市台鋼 3-3 台中磐石 進球："}, {"type": "paragraph", "text": "馮少祺(台鋼) 21’"}, {"type": "paragraph", "text": "柏天諾(台鋼) 47’ 54’"}, {"type": "paragraph", "text": "林駿凱 66’"}, {"type": "paragraph", "text": "劉建緯 74’"}, {"type": "paragraph", "text": "林偉傑 83’"}, {"type": "paragraph", "text": "台中磐石9月28日在台南市立足球場作客挑戰南市台鋼，雙方上演激烈拉鋸戰，最終以3比3握手言和，各取一分積分。"}, {"type": "paragraph", "text": "比賽前 20 分鐘，雙方以試探為主，直至第21分鐘，南市台鋼由馮少祺左路突破後抽射破門，先馳得點。落後的台中磐石保持耐心，持續尋找快速反擊機會。第31分鐘，台鋼打出穿越球形成單刀，但是台中磐石門將蔡宇翔判斷精準，及時撲下來球化解危機。上半場台中磐石以0:1落後。"}, {"type": "paragraph", "text": "下半場開始不久，台鋼左路傳中造成防守失誤，柏天諾在門前將比分改寫為 2：0。第54分鐘台中磐石後場傳球失誤，再度讓柏天諾抓住機會梅開二度，比分來到 3:0。第60分鐘，台鋼再度獲得單刀良機，但曾畇浩門前拼盡全力救險，避免比分被進一步拉開。"}, {"type": "paragraph", "text": "第66分鐘，磐石隊長李鴻均左腳傳中，經對手折射後落到林駿凱身前，他把握機會頂進，吹響反攻號角。第75分鐘，台中磐石在右路打出流暢小組配合，鄭凱議傳中，替補登場的劉建緯一腳破門，追到僅剩一球差距。第78分鐘，台中磐石獲得自由球機會，曾畇浩在門前的頭槌差一點就扳平比數。"}, {"type": "paragraph", "text": "比賽來到第83分鐘，台中磐石的努力得到回報，林駿凱在中場開出自由球，林偉傑高高躍起頭槌攻門，頂出漂亮的拋物線，比分追成3：3！傷停補時第7分鐘，鄭凱議在禁區邊緣起腳射門，皮球擦柱而出，錯失逆轉絕佳機會。最終全場結束，台中磐石在三球落後的情況下強勢追平，與南市台鋼戰成 3：3，帶走寶貴的一分積分。"}, {"type": "paragraph", "text": "先發陣容 : 4 蔡俊昇, 6 孫恩祈, 7 龔致宇, 11 楊朝景, 12 李毓霖, 32 柯岳廷, 35 李鴻均, 44 山内大空, 66 曾畇浩, 97 林駿凱, 99 蔡宇翔"}, {"type": "paragraph", "text": "替補 : 1 黃懷賢, 2 鄭凱議, 3 許魁, 5 周宇杰, 9 劉建緯, 16 魏志荃, 19 周宇豪 21 古傑安, 27 施靖堂, 30 陳瑄廷, 37 梁顥騰, 47 高冠宇, 48 王義友, 77 林偉傑"}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2025-09-28-match-032' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "2025/09/21 臺南市立足球場"}, {"type": "paragraph", "text": "企甲聯賽 Week 4：大同足球 2-2 台中磐石 進球："}, {"type": "paragraph", "text": "陳世賢 5’ (大同)"}, {"type": "paragraph", "text": "龔致宇 45+3’"}, {"type": "paragraph", "text": "陳瑞杰 71’ (大同)"}, {"type": "paragraph", "text": "OG 90+2’"}, {"type": "paragraph", "text": "台中磐石與大同足球在第四週企甲聯賽正面交鋒，雙方激戰90分鐘，最終以2比2握手言和，各收下1分。"}, {"type": "paragraph", "text": "比賽一開始僅5分鐘，大同便在禁區內把握機會，由陳世賢先馳得點，取得1比0領先。不過僅僅1分鐘後，台中磐石迅速還以顏色，林駿凱在前場斷球後交給山內大空，山內禁區邊緣拿球轉身穿越球傳給李鴻均，台中磐石隊長第一時間射門，可惜遭守門員擋下。19分鐘，台中磐石後場傳球失誤，所幸門將蔡宇翔即時出擊，化解危機。上半場補時第3分鐘，李毓霖壓上傳中，龔致宇禁區內第一時間左腳抽射破門，為台中磐石追成1比1平手。"}, {"type": "paragraph", "text": "易邊再戰，62分鐘台中磐石延續進攻態勢，山內大空穿越球送到右邊，替補上場的鄭凱議擺脫防守後起腳，卻被大同後衛擋下。71分鐘，台中磐石防守未能阻止大同的推進，陳瑞杰禁區內射門建功，助球隊再度領先。78分鐘，替補上場的劉建緯傳出威脅球，鄭凱議門前射門仍被門將封阻。比賽進入補時，再度出現戲劇性場面，林駿凱送出長傳，大同後衛門前踢空反彈，意外形成烏龍球，台中磐石將比分追成2比2。"}, {"type": "paragraph", "text": "最終，台中磐石憑著頑強鬥志兩度扳平戰局，與大同以平手收場。"}, {"type": "paragraph", "text": "先發陣容 : 4 蔡俊昇, 7 龔致宇, 12 李毓霖, 16 柯岳廷, 32 柯岳廷, 35 李鴻均, 44 山内大空, 47 高冠宇, 66 曾畇浩, 97 林駿凱, 99 蔡宇翔"}, {"type": "paragraph", "text": "替補 : 1 黃懷賢, 2 鄭凱議, 3 許魁, 5 周宇杰, 9 劉建縡, 11 楊朝景, 19 周宇豪 21 古傑安, 30 陳瑄廷, 37 梁顥騰, 77 林偉傑"}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2025-09-21-match-033' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "2025/09/20 國立體育大學"}, {"type": "paragraph", "text": "乙級聯賽 Week 2：新北航源輔大 1-0 台中磐石預備隊 在酷熱天氣下，台中磐石預備隊於國立體育大學進行乙級聯賽首場比賽，對手是新北航源輔大。"}, {"type": "paragraph", "text": "比賽第6分鐘，新北輔大憑藉一次邊線球攻勢直接製造威脅，把球送入禁區後，台中守門員王弘宇雖即時出拳破壞，卻因改變球路不多，最終足球撞柱入網。38 分鐘，台中磐石由李偉綸在右路送出精準傳中，可惜隊友跟進慢了一步，錯失扳平良機。"}, {"type": "paragraph", "text": "下半場易邊再戰，第 52 分鐘，許劉鑑鋒在左路送出傳中，替補上場的江均堯在禁區邊緣射門，雖然對方門將撲救不遠，但戴彥堯補射未能命中目標，與進球擦身而過。隨後台中磐石透過多次換人調整逐漸佔據主動，加強進攻火力，不過新北輔大仍舊憑傳中兩度製造險象環生。比賽尾聲，許劉鑑鋒獲得單刀良機，但遭對方門將封阻，黃昱博的補射亦未能破門。"}, {"type": "paragraph", "text": "最終，台中磐石預備隊在本季乙級聯賽首戰以 0 比 1 不敵新北航源輔大。"}, {"type": "paragraph", "text": "先發陣容 : 8 陳柏穎, 10 張恒, 13 陳柏崴, 14 李偉綸, 17 許劉鑑鋒, 20 戴彥堯, 22 黃昱博, 23 盧恩偉, 25 薛任祐, 28 陳治瑋, 39 王宏宇"}, {"type": "paragraph", "text": "替補 : 15 劉俊佑, 18 陳冠智, 26 林家樂, 29 江均堯 40 林政睿, 45 胡淯翔, 98 潘彥宏"}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2025-09-20-match-034' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "2025/09/14 臺中西屯足球場"}, {"type": "paragraph", "text": "企甲聯賽 Week 3：台中磐石 0-2 台灣電力 進球："}, {"type": "paragraph", "text": "許博傑 41'' (台電) 陳昭安 47'' (台電)"}, {"type": "paragraph", "text": "台中磐石主場迎戰台灣電力，上半場雙方互有攻勢。比賽進行到17分鐘，台電率先製造威脅，陳昭安接應角球頂出頭槌，但未能命中目標。23分鐘，磐石馬上回敬，李鴻均主罰自由球，曾畇浩高高躍起頂球攻門，可惜未能轉化為進球。41分鐘，台電由許博傑在禁區邊緣抽射破門，先馳得點。44分鐘，台中磐石再度透過定位球尋找機會，龔致宇開出自由球送入禁區，蔡俊昇的頭槌直撲球門，但被台電門將穩穩接住，上半場結束，台電一球領先。"}, {"type": "paragraph", "text": "易邊再戰，台電在47分鐘把握磐石後場傳球失誤，由陳昭安單刀破門，將比分拉開至2比0。落後的台中磐石並未放棄，持續壓上進攻，但是射門或被門將化解，或稍稍偏出。比賽進入最後階段，皡磐石仍積極透過邊路傳中與自由球尋找突破口，但始終未能撕開對手防線。最終，台中磐石在主場以0比2不敵台灣電力。"}, {"type": "paragraph", "text": "雖然比賽結果未如理想，但我們深信失敗乃成功之母。台中磐石會從中汲取經驗，再接再勵，為下一場比賽做好最充分的準備。"}, {"type": "paragraph", "text": "先發陣容 : 4 蔡俊昇, 6 孫恩祈, 7 龔致宇, 11 楊朝景, 12 李毓霖, 19 周宇豪, 30 陳瑄廷, 35 李鴻均, 44 山内大空, 66 曾畇浩, 88 廖奕盛"}, {"type": "paragraph", "text": "替補 : 1 黃懷賢, 2 鄭凱議, 3 許魁, 5 周宇杰, 9 劉建緯, 16 魏志荃, 21 古傑安, 27 施靖堂, 32 柯岳廷, 37 梁顥騰, 47 高冠宇, 77 林偉傑, 97 林駿凱, 99 蔡宇翔"}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2025-09-14-match-035' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "2025/08/24 臺中西屯足球場"}, {"type": "paragraph", "text": "企甲聯賽 Week 2：台中磐石 0-1 台中Futuro 進球："}, {"type": "paragraph", "text": "16’ 李茂"}, {"type": "paragraph", "text": "2025/26企業甲級足球聯賽迎來史上首次「台中德比」，台中磐石與台中Futuro在場上正面交鋒。比賽一開始，台中磐石即展現強烈企圖心，3分鐘內連續完成兩次射門，積極尋求破門機會。"}, {"type": "paragraph", "text": "15分鐘，劉建緯在禁區邊緣右腳腳背突然遠射，可借未能命中目標。1分鐘之後，台中Futuro把握到台中磐石一次防守失誤，由李茂先馳得點。第19分鐘，台中磐石策動反擊，劉建緯停球後送出精準左腳傳中，可惜林偉傑在門前的射門未能轉化為進球，讓扳平良機擦肩而過。"}, {"type": "paragraph", "text": "易邊再戰，第59分鐘，Futuro再度利用傳中創造頭球攻門，但被台中磐石門將陳瑄廷即時反應化解。落後的台中磐石隨後積極調整，連續換上攻擊球員，並嘗試透過長傳球尋找破口，可惜未能對Futuro防線造成實質威脅。最終，雙方下半場均未再有進球，台中磐石以0：1吞下敗仗。"}, {"type": "paragraph", "text": "先發陣容 : 2 鄭凱議, 5 周宇杰, 6 孫恩祈, 7 龔致宇, 9 劉建緯, 12 李毓霖, 30 陳瑄廷, 35 李鴻均, 47 高冠宇, 66 曾畇浩, 77 林偉傑"}, {"type": "paragraph", "text": "替補 : 1 黃懷賢, 3 許魁, 11 楊朝景, 16 魏志荃, 19 周宇豪, 21 古傑安, 27 施靖堂, 32 柯岳廷, 37 梁顥騰, 88 廖奕盛, 97 林駿凱, 99 蔡宇翔"}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2025-08-24-match-036' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "2025/08/17 臺中西屯足球場"}, {"type": "paragraph", "text": "企甲聯賽 Week 1：台中磐石 2-1 新北航源 進球： 8‘ 龔致宇"}, {"type": "paragraph", "text": "17’ 山內大空"}, {"type": "paragraph", "text": "90+5'' 姜泰源 (航源)"}, {"type": "paragraph", "text": "首次在企甲聯賽亮相的台中磐石，剛開賽就採取主動、利用跑動及壓迫控制戰局。第8分鐘，劉建緯傳球上前，對方守門員控球失誤，龔致宇上前搶下皮球再冷靜射進空門，先馳得點。"}, {"type": "paragraph", "text": "第15分鐘，龔致宇在單刀情況下被放倒，但主審裁判沒有表示。第17分鐘，李毓霖攔截成功，山內大空在左邊路離門約40碼射出「世界波」破門，為台中磐石擴大領先優勢至2:0。"}, {"type": "paragraph", "text": "第36分鐘，台中磐石率先作出換人調動，由梁顥騰替補上場取代劉建緯。上半場之後的時間，雙方互有進攻的嘗試但再也沒有改寫比分，也就以2:0比分結束上半場。"}, {"type": "paragraph", "text": "踏入下半場中段，台中磐石陸續作出換人調動，曾畇浩、蔡俊昇、林偉傑、柯岳廷先後登場，為球隊注入活力。第62及65分鐘，蔡俊昇分別被裁判認為職業犯規及拖延時間，短時間領到了兩張黃牌而需要提早退場，台中磐石在及後時間需要少打一人。"}, {"type": "paragraph", "text": "下半場傷停補時第8分鐘，梁顥騰在禁區內犯規，門將陳瑄廷雖然將對方的十二碼撲出，但及後航源球員馬上上前橫傳補射破門，將分差拉近至一球。"}, {"type": "paragraph", "text": "最終，台中磐石以2:1的比分擊敗了新北航源，在隊史第一場企甲聯賽就拿下了勝利！"}, {"type": "paragraph", "text": "先發陣容 : 2 鄭凱議, 5 周宇杰, 6 孫恩祈, 7 龔致宇, 9 劉建緯, 12 李毓霖, 16 魏志荃, 30 陳瑄廷, 35 李鴻均, 44 山內大空, 47 高冠宇"}, {"type": "paragraph", "text": "替補 : 1 黃懷賢, 3 許魁, 4 蔡俊昇, 11 楊朝景, 19 周宇豪, 21 古傑安, 27 施靖堂, 32 柯岳廷, 37 梁顥騰, 48 王義友, 66 曾畇浩, 77 林偉傑, 88 廖奕盛, 97 林駿凱, 99 蔡宇翔"}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2025-08-18-match-037' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
