UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "台中磐石國際足球盃 SG5 2025年7月29日（星期二）17:00 KO 臺中市西屯足球場"}, {"type": "paragraph", "text": "比賽取消"}, {"type": "heading", "text": "比賽資料"}, {"type": "list", "ordered": false, "items": ["天氣：陰天 / 27℃ / 72%", "裁判：林祐億", "助理裁判：陳心善 趙宥霖", "第四裁判：朱柚盈"]}, {"type": "heading", "text": "Starting Eleven 先發名單"}, {"type": "paragraph", "text": "紅白艾倫"}, {"type": "list", "ordered": false, "items": ["3 Dominik Limprecht", "4 Mattias Hanchard", "8 Marius Müller", "9 Aristote Lufuankenda", "11 Gianluca Di Vinti", "16 Edon Rizaj", "20 Ben Binyamin", "23 Murat Keskinkilic", "24 Louis Krieg", "27 Davin Wöstmann", "31 Veith Walde"]}, {"type": "paragraph", "text": "台中Futuro"}, {"type": "list", "ordered": false, "items": ["3 陳庭揚", "6 蔡杰勲", "10 橫山翔平", "12 溫智豪", "17 許恆賓", "19 利亞設", "35 齋藤遼太", "42 劉韋喆", "50 松井謙彌 GK", "77 賴義橋", "88 櫻內渚 (C)"]}, {"type": "heading", "text": "Substitute 替補名單"}, {"type": "paragraph", "text": "紅白艾倫"}, {"type": "list", "ordered": false, "items": ["1 Hahnemann", "6 Holthaus", "7 Curic", "10 Cucciardo", "15 Kruphölter", "18 Heidbrink", "19 Freiberger", "22 Hornbruch", "28 Kosar", "29 Rauf"]}, {"type": "paragraph", "text": "台中Futuro"}, {"type": "list", "ordered": false, "items": ["1 李明威", "4 曾德龍", "5 程昊", "7 小川圭佑", "8 小森由貴", "9 陳泓維", "18 李茂", "34 林哲宇", "99 林駿樺"]}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2025-07-31-intcup-039' AND i.locale = N'zh-Hant' AND i.body IS NULL;
