UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "台中磐石足球俱樂部正式與義大利頂級職業足球聯賽（Serie A）俱樂部維羅納 Hellas Verona FC 簽署合作備忘錄（MoU），雙方將就球員交流、教練培訓、場地管理、球探資訊共享及國際賽事參與等多個面向展開全面合作。"}, {"type": "paragraph", "text": "本次簽署的合作備忘錄，象徵雙方基於誠信與共識，建立長期夥伴關係的堅定承諾。透過此次合作，台中磐石足球俱樂部將為台灣球員創造更多赴歐洲接受高水準訓練的機會，並邀請義大利球員來台參與比賽與交流活動，提升台灣足球在國際舞台的能見度與競爭力。"}, {"type": "paragraph", "text": "合作重點包括："}, {"type": "paragraph", "text": "- 推動球員與教練團隊的交流與發展\n- 建立球探與招募系統的資訊共享機制\n- 協助優秀台灣球員赴義大利接受專業訓練\n- 分享場地與設施管理的專業經驗\n- 規劃Hellas Verona FC球員來台參賽與互動"}, {"type": "paragraph", "text": "Hellas Verona 在義大利是一支多年在義甲比賽，具有豐富歐洲頂級聯賽主場經營經驗的球會，他們在場地管理、草皮養護和賽事營運等方面都非常有系統。這次合作，我們會針對這些部分請他們給予專業指導，讓台中磐石在訓練場和日後的主場場地的管理上也能與國際接軌，讓球員和球迷都有更好的環境與體驗。"}, {"type": "paragraph", "text": "雙方也將定期進行高層交流，根據合作進程召開相關會議，並共同管理所有對外發佈的資訊與活動規劃，確保合作方向與步調一致。"}, {"type": "paragraph", "text": "台中磐石表示，此次與Hellas Verona FC的合作，是俱樂部國際化布局的重要一步，也代表著台灣足球正朝向更高的水準邁進。俱樂部未來將持續尋求更多國際夥伴，為台灣年輕球員打造更廣闊的發展舞台。"}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2025-07-30-international-040' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "台中磐石國際足球盃 SG4 2025年7月29日（星期二）18:45 KO 臺中市西屯足球場"}, {"type": "paragraph", "text": "Full Time 1-3"}, {"type": "heading", "text": "進球"}, {"type": "paragraph", "text": "台中磐石：22'' 陳治瑋"}, {"type": "paragraph", "text": "紅白艾倫：12'' 18'' Davin Wöstmann、41'' Erik Heidbrink"}, {"type": "heading", "text": "比賽資料"}, {"type": "list", "ordered": false, "items": ["天氣：陰天 / 30℃ / 74%"]}, {"type": "heading", "text": "Starting Eleven 先發名單"}, {"type": "paragraph", "text": "台中磐石"}, {"type": "list", "ordered": false, "items": ["2 鄭凱議 ▼46''", "8 陳柏穎 ▼46''", "12 李毓霖 ▼46''", "17 許劉鑑鋒 ▼46''", "20 戴彥堯 ▼46''", "22 黃昱博 ▼46''", "25 薛任佑 ▼46''", "28 陳治瑋 ▼46''", "39 王宏宇 GK ▼46''", "45 胡淯翔 ▼46''", "66 曾畇浩 ▼46''"]}, {"type": "paragraph", "text": "紅白艾倫"}, {"type": "list", "ordered": false, "items": ["3 Dominik Limprecht", "18 Erik Heidbrink", "29 Hendrik Rauf ▼46''", "10 Sergio Cucciardo ▼74''", "11 Gianluca Di Vinti ▼46''", "16 Edon Rizaj", "19 Kevin Freiberger ▼82''", "20 Ben Binyamin", "22 Kilian Hornbruch ▼46''", "27 Davin Wöstmann ▼90''", "31 Veith Walde"]}, {"type": "heading", "text": "Substitute 替補名單"}, {"type": "paragraph", "text": "台中磐石"}, {"type": "list", "ordered": false, "items": ["4 蔡俊昇 ▲46", "5 周宇杰 ▲46", "7 龔致宇 ▲46", "11 楊朝景 ▲46", "19 周宇豪 ▲46", "21 古傑安 ▲46", "27 施靖堂 ▲46", "35 李鴻均 ▲46", "47 高冠宇 ▲46", "77 林偉傑 ▲46", "99 蔡宇翔 ▲46"]}, {"type": "paragraph", "text": "紅白艾倫"}, {"type": "list", "ordered": false, "items": ["1 Alexander Hahnemann", "4 Mattias Hanchard", "8 Marius Müller", "9 Aristote Lufuankenda ▲46", "15 Mika Kruphölter ▲82''", "6 Fabian Holthaus", "23 Murat Keskinkilic ▲90''", "24 Louis Krieg ▲46", "28 Kadir Kosar ▲74''", "31 Veith Walde", "7 Emro Curic ▲46"]}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2025-07-29-intcup-041' AND i.locale = N'zh-Hant' AND i.body IS NULL;
