UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "台中磐石國際足球盃 SG3 2025年7月29日（星期二）16:00 KO 臺中市西屯足球場"}, {"type": "paragraph", "text": "Full Time 1-1"}, {"type": "heading", "text": "進球"}, {"type": "paragraph", "text": "東方：12'' 史加利"}, {"type": "paragraph", "text": "台中Futuro：84'' 齋藤遼太"}, {"type": "heading", "text": "比賽資料"}, {"type": "list", "ordered": false, "items": ["天氣：小雨 / 30℃ / 74%", "裁判：溫文龍", "助理裁判：林祐億 陳柏安", "第四裁判：劉祥紹"]}, {"type": "heading", "text": "Starting Eleven 先發名單"}, {"type": "paragraph", "text": "東方"}, {"type": "list", "ordered": false, "items": ["16 梁振邦", "17 張廣然 ▼53", "19 姚浩明 ▼63''", "20 史加利 ▼81''", "21 基華尼頓 ▼63''", "22 梁冠聰 (C) ▼63''", "26 廖富源 (GK)", "28 蕭政 ▼46''\\*", "32 林衍廷", "72 具滋龍", "88 張文浩 ▼46''\\*"]}, {"type": "paragraph", "text": "台中未來"}, {"type": "list", "ordered": false, "items": ["4 曾德龍 ▼60''", "5 程昊", "6 蔡杰勲 ▼66''", "9 陳泓維", "10 橫山翔平 ▼46''^", "17 許恆賓 ▼46''\\*", "19 利亞設 ▼66''", "21 段霱 GK ▼46''\\*", "34 林哲宇 ▼46''\\*", "42 劉韋喆 ▼46''", "88 櫻內渚 (C)"]}, {"type": "heading", "text": "Substitute 替補名單"}, {"type": "paragraph", "text": "東方"}, {"type": "list", "ordered": false, "items": ["1 葉鴻輝", "14 王飛揚 ▲46\\*", "24 高銘藝", "29 顏肇江", "30 費利浦薩", "33 高銘浩 ▲46''", "36 何本彥 ▲63", "42 楊棟棋 ▲81''", "43 黃安游 ▲63", "44 連朗狄 ▲53", "77 劉君正 ▲63"]}, {"type": "paragraph", "text": "台中未來"}, {"type": "list", "ordered": false, "items": ["1 李明威", "3 陳庭揚 ▲66''", "7 小川圭佑 ▲46''", "8 小森由貴 ▲66''", "12 溫智豪 ▲46\\*", "18 李茂", "23 高山薫 ▲60''", "35 齋藤遼太 ▲46\\*", "50 松井謙彌", "77 賴義橋 ▲46^", "99 林駿樺 ▲46\\*"]}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2025-07-29-intcup-042' AND i.locale = N'zh-Hant' AND i.body IS NULL;
