UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "台中磐石足球俱樂部正式與德國足球隊 Rot Weiss Ahlen 簽署合作備忘錄，雙方將自2025年8月1日起展開長期合作，攜手投入人才交流、球探合作以及賽事參與等多元領域，共同推動雙方的國際化發展。"}, {"type": "paragraph", "text": "值得一提的是，Rot Weiss Ahlen 將於今年夏天首度來台，參與由台中磐石主辦的《2025台中磐石國際足球盃》。透過實際參賽，雙方球員與教練不僅能在場上切磋球技，更為日後的合作奠定深厚基礎。"}, {"type": "paragraph", "text": "根據合作內容，雙方將聚焦以下三大領域："}, {"type": "paragraph", "text": "- 球員與教練之間的交流與發展：安排技術研習、短期訓練計畫與教練觀摩等，提升整體實力。\n- 招募與球探資訊的共享：透過資訊平台交換球員潛力資料，擴大人才培育網絡。\n- 共同參與與舉辦各類賽事：包括國際邀請賽與青訓比賽，提升曝光度並豐富實戰經驗。"}, {"type": "paragraph", "text": "雙方也將透過定期會議強化高層間的戰略協調，並就對外溝通與宣傳事宜事先協商，共同規劃合作推進的步驟與方向。"}, {"type": "paragraph", "text": "台中磐石由董事長馮世文表示：「這次與德國 Rot Weiss Ahlen 的合作，是俱樂部國際化的重要一步。我們非常榮幸能在《2025台中磐石國際足球盃》迎接來自德國的夥伴，並簽下這份合作諒解備忘錄，相信這將是雙方共同進步的起點。」"}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2025-07-27-international-043' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
