UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "台中磐石國際足球盃 SG2 2025年7月27日（星期日）18:40 KO 臺中市西屯足球場"}, {"type": "paragraph", "text": "Full Time 3-0"}, {"type": "heading", "text": "進球"}, {"type": "paragraph", "text": "紅白艾倫：14'' Marius Müller、44'' Davin Wöstmann、90+2'' Emro Curic"}, {"type": "heading", "text": "比賽資料"}, {"type": "list", "ordered": false, "items": ["天氣：晴 / 28℃ / 85%", "裁判：劉祥紹", "助理裁判：趙宥霖 林祐億", "第四裁判：陳心善"]}, {"type": "heading", "text": "Starting Eleven 先發名單"}, {"type": "paragraph", "text": "紅白艾倫"}, {"type": "list", "ordered": false, "items": ["3 Dominik Limprecht", "4 Mattias Hanchard", "6 Fabian Holthaus (C) ▼54''", "7 Emro Curic", "8 Marius Müller ▼68''", "10 Sergio Cucciardo", "11 Gianluca Di Vinti ▼68''", "19 Kevin Freiberger ▼68''", "22 Kilian Hornbruch", "27 Davin Wöstmann ▼59''", "31 Veith Walde (GK)"]}, {"type": "paragraph", "text": "東方"}, {"type": "list", "ordered": false, "items": ["1 葉鴻輝 (GK)", "2 賀爾 ▼72''", "11 史加利 ▼72''", "22 梁冠聰 (C) ▼72''", "23 王飛揚 ▼46''", "27 馬高斯 ▼63''", "30 黃梓浩 ▼72''", "32 林衍廷 ▼46''", "33 高銘浩 ▼63''", "35 費利浦薩 ▼72''", "72 具滋龍 ▼63''"]}, {"type": "heading", "text": "Substitute 替補名單"}, {"type": "paragraph", "text": "紅白艾倫"}, {"type": "list", "ordered": false, "items": ["1 Alexander Hahnemann", "9 Aristote Lufuankenda ▲59''", "15 Mika Kruphölter", "16 Edon Rizaj", "18 Erik Heidbrink ▲68''", "20 Ben Binyamin ▲54''", "23 Murat Keskinkilic ▲68''", "24 Louis Krieg ▲68''", "28 Kadir Kosar", "29 Hendrik Rauf"]}, {"type": "paragraph", "text": "東方"}, {"type": "list", "ordered": false, "items": ["3 梁振邦 ▲63''", "17 張廣然 ▲63''", "19 姚浩明 ▲63''", "21 基華尼頓 ▲72''", "24 蕭政 ▲46''", "26 廖富源 GK", "29 劉君正 ▲46''", "42 楊棟棋 ▲72''", "43 黃安游 ▲72''", "44 柏拔 ▲72''"]}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2025-07-27-intcup-045' AND i.locale = N'zh-Hant' AND i.body IS NULL;
