UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "由台中磐石足球俱樂部主辦的「2025台中磐石國際足球盃」將於本週末7月27日正式登場。賽前記者會於7月25日下午在台中舉行，來自德國、香港及台灣的參賽隊伍代表齊聚一堂，場面熱鬧，宣告這場國際級賽事正式進入倒數階段。"}, {"type": "paragraph", "text": "本屆賽事獲得亞洲足協認可為「第二級國際賽事（AFC Tier 2）」認證，四支成年隊參賽。成年組部分包括地主隊台中磐石、台中Futuro、香港東方足球隊與德國Rot Weiss Ahlen足球會。另外設有青少年組，青少年組則有來自香港的東方青年隊、AC米蘭足球學院（香港）、晉峰足球會，將與台中磐石青訓隊及花蓮美崙國中進行交流對戰。"}, {"type": "paragraph", "text": "台中磐石董事長馮世文在記者會中表示，球隊自成立以來，始終以「全方位發展」為目標，希望透過這場賽事以及更多不同認識的國際交流，連結更多國際資源，協助台灣年輕球員走向世界舞台。他也特別感謝台中市政府與運動局對本屆賽事的支持，強調協助台中市政府、台中市運動局，將台中打造成台灣的足球之都。這是我們的重要目標。"}, {"type": "paragraph", "text": "來台參賽的各國球隊代表也在會中發表感言，對能參與這樣具備水準和創新的交流賽表示期待。"}, {"type": "paragraph", "text": "今年賽事共有6場成年比賽與10場青少年比賽，將全程免費開放觀眾入場，並同步於YouTube平台進行直播，讓全台及海外球迷都能一同參與這場盛會。主辦單位預期，此賽事將帶動台中在地觀光與產業效益，也為台灣足球注入更多國際能量。"}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2025-07-25-club-046' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "臺中市政府運動局7月21日舉辦授旗典禮，運動局局長游志祥、市議員林祈烽親臨現場，並致贈慰勞水果籃及運動飲料，為即將出征的球隊表達關心與祝福。"}, {"type": "paragraph", "text": "典禮中，台中磐石由董事長馮世文與總教練拉斐爾布蘭瓊代表球隊出席，感謝市府與市議會長期以來對足球運動的重視與推動。"}, {"type": "paragraph", "text": "此次授旗典禮除了象徵鼓勵與榮耀，也彰顯出政府與民間攜手發展運動的決心。台中磐石足球俱樂部將全力以赴，在接下來的比賽中爭取佳績，為台中爭光。"}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2025-07-21-community-047' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "2025台中磐石國際足球盃熱血開踢 運動×觀光雙引擎　帶動台中城市新風貌"}, {"type": "paragraph", "text": "為深化國際足球交流、提升台灣競技實力、並強化青少年足球基礎，「2025台中磐石國際足球盃」即將於 7月27日至7月31日 在台中市西屯足球場盛大登場。來自德國、香港與台灣的足球好手齊聚台中，帶來一連串精彩對決，為夏日注入滿滿熱血能量。"}, {"type": "paragraph", "text": "本屆賽事得到了亞洲足聯的第二級國際賽事（AFC Tier 2 International Competition）認可，規劃了成年組與青少年組兩大主軸，匯集多支實力堅強的國內外球隊。成年組部分，除了地主隊台中磐石足球俱樂部外，還有台灣球迷熟悉的台中Futuro FC、來自香港超級聯賽的傳統勁旅東方足球隊，以及德國西部的歷史老牌球會 Rot Weiss Ahlen e.V.。"}, {"type": "paragraph", "text": "在青少年組方面，本屆特別邀請多支優質青訓隊伍來台交流，包括來自香港的東方足球隊青訓隊、AC米蘭足球學院（香港）、晉峰足球會，將與台中磐石青訓隊及花蓮美崙國中進行技術切磋。藉由跨地區的友誼競技，培養青少年球員的國際視野與比賽經驗。"}, {"type": "paragraph", "text": "本屆賽事共計六場成人賽事、十場青少年賽事，讓球迷朋友能夠近距離感受國際足球比賽的節奏與激情，親眼見證職業級選手在場上的拼搏與交流。無法親臨現場的朋友也不用擔心，所有成年組與青少年組比賽將同步於YouTube平台直播，讓全台乃至海外的球迷都能一同參與這場足球盛會。"}, {"type": "paragraph", "text": "本次賽事也呼應台中市政府運動局「酷運動、酷城市」推動政策，透過舉辦國際級足球賽事，帶動運動觀光與地方產業發展，吸引更多國內外旅客認識台中、體驗城市魅力。比賽期間，預計將對在地旅宿、餐飲、交通等產業帶來可觀效益，展現運動與觀光雙引擎的帶動力。"}, {"type": "paragraph", "text": "2025台中磐石國際足球盃不僅是場足球盛事，更是一場屬於台中的國際派對。誠摯邀請市民朋友與球迷一同進場，感受足球魅力、為城市喝采！"}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2025-07-12-club-048' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "台中磐石足球俱樂部與「[龜記茗品](https://guiji-group.com/)」繼續攜手合作，將以兩方品牌理念為核心，推動台中足球與社區發展。"}, {"type": "paragraph", "text": "台中磐石致力於培養在地足球人才，與龜記傳承台灣茶文化、強調品質與在地連結的品牌理念高度契合。雙方期待透過運動與茶飲文化的結合，鼓勵更多年輕人投入運動，傳遞正向生活態度。"}, {"type": "paragraph", "text": "本次合作，龜記品牌標誌將出現在球衣右胸，與球員一同征戰賽場、點燃城市熱情，共同深耕台中。"}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2025-07-08-club-049' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "台中磐石足球俱樂部在6月11日應邀出席南投縣信義鄉雙龍國民小學113學年度第59屆暨附設幼兒園第25屆畢業典禮，並頒發由去年開始設立的「台中磐石獎學金」，鼓勵孩子們勇敢追夢。"}, {"type": "paragraph", "text": "活動中，台中磐石代表也與全體師生一同參與植樹儀式及象徵夢想啟航的放氣球活動，為孩子們的未來種下希望，讓畢業回憶更加難忘。"}, {"type": "paragraph", "text": "為支持偏鄉學校足球發展，台中磐石足球俱樂部繼去年贊助雙龍國小足球隊的球衣、足球及獎學金之後，今年亦贊助球隊於今年七月前往日本關西進行移地訓練，讓小球員們有機會拓展國際視野，提升技術與經驗。"}, {"type": "paragraph", "text": "此外，磐石球員孫恩祈與梁顥騰特地到場與畢業班學生進行面對面交流，分享他們前往西班牙接受台中磐石在西班牙的合作俱樂部RC Alcobendas的訓練，以及親眼見證皇馬、巴薩等世界頂尖足球比賽的經歷。他們鼓勵小朋友持續努力、不怕挑戰，只要有熱情、有實力，就有機會走向更大的舞台。"}, {"type": "paragraph", "text": "台中磐石足球俱樂部致力於推廣基層足球，期望透過實際行動，為更多孩子創造接觸國際、實現夢想的機會。"}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2025-06-11-community-050' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "2025/05/11 臺中西屯足球場"}, {"type": "paragraph", "text": "總統盃A組：台中磐石 2-2 高大國光 進球： 黃至豪 85'' 黃朝忠 94'' (高) 施靖堂 80'' 93'' (台) 上半場第12分鐘，高大國光率先起腳，但射門偏出。第19分鐘，磐石獲得禁區邊緣自由球機會，亞歷山卓主罰的射門僅差一點就破門。第26分鐘，高大國光從右路發動攻勢，射門雖準但被門將陳冠智穩穩接下，守住城門。"}, {"type": "paragraph", "text": "下半場第55分鐘，林家樂左路推進後交給費威斯，突破禁區後起腳，可惜被對方門將擋出。第67分鐘，施靖堂與陳治瑋展現默契，撞牆配合後傳中，後點的張旭揚起腳施射，卻被對方後衛封阻。"}, {"type": "paragraph", "text": "第80分鐘，終於打破僵局，替補上陣的施靖堂接應周宇杰的穿越球，在禁區內連過兩人後起腳破網，幫助磐石先馳得點。不過僅僅五分鐘後，高大國光把握角球機會將比分追平。"}, {"type": "paragraph", "text": "補時第93分鐘，張旭揚於禁區左側傳中，施靖堂頭槌建功，磐石再次超前。可惜比賽最後時刻，高大國光再度攻破球門，最終雙方2：2握手言和。"}, {"type": "paragraph", "text": "先發陣容 : 3 許魁, 13 陳柏崴, 18 陳冠智, 26 林家樂, 28 陳治瑋, 40 林政睿, 41 費威斯, 42 亞歷山卓, 45 胡淯翔, 46 李柏佑 49 張旭揚"}, {"type": "paragraph", "text": "替補 : 2鄭凱議, 5周宇杰, 8陳柏穎, 20藏彦堯, 22 黄昱博, 27施靖堂, 43廖倢揚, 88廖奕盛, 99蔡宁翔"}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2025-05-13-match-052' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "2025/05/11 臺中西屯足球場\n總統盃B組：台中磐石預備隊 8-1 銘傳B"}, {"type": "paragraph", "text": "進球： 鄭宇哲 39'' (銘傳) 周宇豪 59'', 蔡俊昇 66'', 柯岳廷 67'', 龔致宇 69''"}, {"type": "paragraph", "text": "高冠宇 74'' 81'' 古傑安 79'' 李偉綸 82''"}, {"type": "paragraph", "text": "上半場第13分鐘，台中磐石預備隊獲得角球機會，高冠宇高高躍起頭槌攻門，可惜未能命中目標。即使風雨交加，台中磐石預備隊依然積極主動，前20分鐘就創造出7次射門機會。不過，第39分鐘銘傳B抓準反擊機會先馳得點，半場結束台中磐石預備隊以0：1落後。"}, {"type": "paragraph", "text": "第59分鐘銘傳B後場出現失誤，周宇豪從禁區邊緣得球然後馬上踢進死角，為台中磐石扳平戰局。第66分鐘，蔡俊昇精準判讀傳球路線，頭槌破門反超比分。接著比賽進入台中磐石掌控節奏的時間，第67分鐘，周宇豪助攻柯岳廷完成抽射破門；第69分鐘，銘傳門將解圍不遠，龔致宇左腳勁射入網。第73分鐘，柯岳廷從右側送出傳中，高冠宇搶點再下一城。第79分鐘，替補登場的古傑安用精彩的遠射破門，台中磐石預備隊將紀錄拉開到6：1。第81與82分鐘，高冠宇與李偉綸接連遠射破門，最終將比分定格在8：1。"}, {"type": "paragraph", "text": "先發陣容 : 4 蔡俊昇, 7 龔致宇, 10 張恒, 12 李毓霖, 17 許劉鑑鋒, 19 周宇豪, 30 陳瑄廷, 32 柯岳延, 35 李鴻均, 47 高冠宇, 48 王義友"}, {"type": "paragraph", "text": "替補 1黃懷賢，6孫恩祈，14 李偉綸，15 劉俊佑, 21 古傑安，23 盧恩偉，25 薛任祐，29 江均堯"}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2025-05-13-match-053' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "2025/05/03 臺中西屯足球場"}, {"type": "paragraph", "text": "總統盃B組：台中磐石 1-5 南市台鋼藍"}, {"type": "paragraph", "text": "本場面對南市台鋼藍，台中磐石的開局不太順利。僅僅第2分鐘，就被對手快速破門，早早陷入落後。更雪上加霜的是，在接下來短短幾分鐘內接連出現兩次不幸的烏龍球，比分在第8分鐘前就來到0:3，讓比賽陷入被動的局面。不過台中磐石並未放棄。下半場第6分鐘，替補上場的施靖堂將球轉移到右路，由周宇杰左腳冷靜推射破門，追回一城，將比數追至1:3。但隨後南市台鋼藍在第59分鐘由賈塔頭槌建功，第63分鐘再下一城。台中磐石在比賽後段依然積極創造進攻機會，雖然有數次具威脅的射門，但最終僅兩次命中門框，無緣縮小比分差距，最後台中磐石以1:5落敗。"}, {"type": "paragraph", "text": "先發陣容：2 鄭凱議, 3 許魁, 5 周宇杰, 8 陳柏穎, 13 陳柏崴, 20 戴彥堯, 22 黄昱博, 28 陳治瑋, 43 廖倢揚, 88 廖奕盛, 99 蔡宇翔"}, {"type": "paragraph", "text": "替補：18 陳冠智, 27 施靖堂, 40 林政睿, 41 費威斯, 42 亞歷山卓, 45 胡淯翔, 46 李柏佑, 49 張旭揚"}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2025-05-04-match-054' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "2025/05/03 臺中西屯足球場 總統盃\nB組：台中磐石預備隊 1-2 台中FUTURO"}, {"type": "paragraph", "text": "第12分鐘，龔致宇在中場得球後轉身突破，面對防守壓力強行起腳抽射，球擊中門柱彈出。第19分鐘，門將黃懷賢在禁區內滑鏟犯規，裁判判罰十二碼，台中Futuro由高山薰主罰命中，先馳得點。上半場比賽中，台中磐石透過積極的短傳組織進攻，試圖突破防線，台中Futuro則專注中場攔截，雙方形成僵持局面。第46分鐘，王義友一記長傳送至禁區邊緣，許劉鑑鋒隨即抽射，可惜未能命中目標。半場結束，台中磐石暫時以 0：1 落後台中Futuro。"}, {"type": "paragraph", "text": "下半場開賽後，台中磐石展開猛烈攻勢，積極推進並創造多次射門機會。第83分鐘，替補上陣的江均堯在禁區邊緣一腳精彩抽射破門，為磐石追平比數至 1：1。第87分鐘，台中Futuro右路傳中製造頭槌攻門機會，磐石門將黃懷賢反應神速，成功救險。但可惜在第89分鐘，李茂與溫智豪配合後，溫智豪一記精準吊射破網，讓Futuro再次超前。終場哨響，台中磐石最終以1：2惜敗。"}, {"type": "paragraph", "text": "先發陣容 : 1 黃懷賢, 4 蔡俊昇, 7 龔致宇, 15 劉俊佑, 17 許劉鑑鋒, 19 周宇豪, 21 古傑安, 32 柯岳廷, 35 李鴻均, 47 高冠宇, 48 王義友"}, {"type": "paragraph", "text": "替補 : 10 張恒, 12 李毓霖, 14 李偉綸, 23 盧恩偉, 25 薛任祐, 29 江均堯, 30 陳瑄廷"}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2025-05-04-match-055' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "2025年5月3日，台中太平區運動場熱鬧非凡，搖身一變成為小小足球員的夢想舞台。由臺中市政府運動局指導、台中磐石足球俱樂部主辦、亞瑟運動俱樂部承辦，並由臺中惠文高中協辦《2025台中磐石盃足球邀請賽》，匯聚超過45支少年足球隊，共同角逐榮耀。"}, {"type": "paragraph", "text": "本屆賽事分為U6、U8、U10、U12四大組別，各隊選手在場上全力拚搏，氣氛緊張又熱血。活動中還有令人驚喜的「磐石球員表演」，展現頂尖技術與熱情，午後更有U8趣味競賽與親子互動賽，讓球場化身為家庭歡樂日，溫馨又有趣。"}, {"type": "paragraph", "text": "台中磐石全體球員也到場聲援，和小球員們一同為足球夢想加油打氣。包括王義友、陳瑄廷、李鴻鈞、龔致宇、高冠宇、周宇杰、古傑安、李偉綸等球員，也親切與現場小朋友簽名合照，近距離互動超暖心。"}, {"type": "paragraph", "text": "這不只是一場足球比賽，更是一場關於夢想、友誼與成長的盛會。感謝所有參與單位、教練、球員與家長的大力支持，讓足球的種子在孩子們心中悄悄發芽、茁壯成長。"}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2025-05-03-camps-056' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "2025/04/26 臺南市立足球場 總統盃B組：桃園國際灰 0:7 台中磐石預備隊 比賽開始之後就馬上形成攻防戰的狀態，台中磐石主導比賽，一直進攻。第24分鐘，張恒在左邊傳中，李偉綸突入禁區射門，不過被桃園國際灰的守門員接住來球。第28分鐘，梁顥騰跟高冠宇在禁區內的配合後，張恒把握時間射門，可惜不中目標。第31分鐘，柯岳廷傳越球送進禁區，高冠宇控球後射門得分，台中磐石先馳得點。第34分鐘，梁顥騰在左邊傳中，李偉綸胸口停球後直接射門入網。第40分鐘，龔致宇傳越球送進禁區，高冠宇第一時間吊射破門，將比分拉開到3:0。"}, {"type": "paragraph", "text": "第49分鐘，柯岳廷開出自由球，高冠宇上前射入，完成帽子戲法。53分鐘，柯岳廷在右邊傳中，蔡俊昇在禁區內為自己創造到空間之後勁射破門，台中磐石領先到5:0。第70分鐘，高冠宇在禁區邊緣得到許劉鑑鋒的傳球，然後轉身抽射破網，取得個人本場第四個進球。第72分鐘，許劉鑑鋒用頭槌破門，協助台中磐石領先7：0。第76分鐘，高冠宇在右邊得球後突入禁區用左腳射門，可惜射中右側門柱彈出。"}, {"type": "paragraph", "text": "最後台中磐石預備隊以7：0客場戰勝桃園國際灰，在總統盃B組取得首個3分積分。"}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2025-04-29-match-057' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "025/04/26 高雄大學人工草皮足球場 總統盃A組：陽信北競預備隊 2:3 台中磐石"}, {"type": "paragraph", "text": "第27分鐘，陽信北競預備隊利用長傳突破防線先馳得點。不過在4分鐘後，台中磐石就作出回應，周宇杰長傳送往禁區邊緣，李柏佑看右路空檔傳球給鄭凱議，鄭凱議把握門前機會，漂亮的低射替台中磐石追成平手。比賽去到第43分鐘，陽信北競預備隊再進一球，令陽信北競預備隊在完上半場之前取得2比1的領先優勢。"}, {"type": "paragraph", "text": "第53分鐘，戴彥曉在右邊得球之後用短傳送入禁區，鄭凱議突入後右腳射門，可惜不中目標。台中磐石繼續進攻，第58分鐘，施靖堂在禁區內突破被犯規，造成12碼罰球然後操刀破門。第64分鐘，施靖堂突破下底傳45度助攻給陳志偉射門得分，台中磐石成功逆轉，以3比2取勝，收下三分積分。"}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2025-04-28-match-058' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "2025全國總統盃足球錦標賽 Group A 2025年4月12日 19:30 台中西屯足球場"}, {"type": "paragraph", "text": "台中磐石 2-1 新北輔大 台中磐石在比賽開始後就積極採取進攻。第36分鐘，周宇杰凌空抽射擊中門框彈出，陳柏崴馬上反應破門得分，幫助台中磐石取得1比0領先。第46分鐘，施靖堂禁區邊緣果斷起腳，在上半場比賽結束之前追加進球。上半場結束，台中磐石2比0領先新北輔大。"}, {"type": "paragraph", "text": "台中磐石領先下將比賽節奏控制住。第72分鐘戴彥堯嘗試一次遠射但不中目標。第79分鐘，台中磐石得到自由球，不過陳柏崴的射門彈道太高。第93分鐘，新北輔大的潘彥宏將角球直接射入，扳回一城。最終全場比賽結束，台中磐石2比1勝新北輔大。"}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2025-04-12-match-059' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "2025全國總統盃足球錦標賽 Group B 2025年4月12日 16:30 台中西屯足球場"}, {"type": "paragraph", "text": "台中磐石預備隊 1-5 南市台鋼綠 第4分鐘，台中磐石策動快攻，李鴻均在對手力壓下射高。第5分鐘，南市台鋼綠柏天諾接應右路隊友的地面傳球，第一時間起腳射門破網，為客隊先馳得點。隨後台中磐石積極反撲，主導形勢展開反擊，第12分鐘，龔致宇從右路送出精準傳中，古傑安頭槌頂高。第16分鐘，江均堯右路橫傳，李鴻均門前第一時間未能把握，梁顥騰遠點位置再射門亦射斜。第17分鐘高冠宇在禁區邊緣拿球後強勢突破，殺入禁區後製造混亂，梁顥騰趁勢左腳射門射高。第23分鐘梁顥騰左路起球傳中，蔡俊昇禁區內頭槌攻門，但台鋼綠門將蔡碩哲將球撲出。第27分鐘，古傑安左路內切勁射，又被台鋼綠門將蔡碩哲將球撲出。第29分鐘，高冠宇下底回傳，門前的周宇豪未能射正。久攻不下的台中磐石在第37分鐘傳來壞消息，台鋼綠柏天諾接應隊友的長傳球突入禁區，面對門將將比分改寫成0比2。上半場傷停補時，台中磐石獲得禁區邊緣自由球，由高冠宇主罰，可惜彈道稍高未能造成威脅。"}, {"type": "paragraph", "text": "上半場，台中磐石的控球比率、攻門次數以至威脅程度都多於台鋼綠，可惜在多個黃金機會一一未能把握之下，暫以0比2落後。"}, {"type": "paragraph", "text": "雙方易邊再戰，第58分鐘，龔致宇在禁區邊緣撿到機會，可惜射門直接踢高。之後台鋼綠分別在第65、67與74分鐘先由林駿楷得分、卡馬羅尼再接續攻進兩球，將比分拉開至0比5。第84分鐘，台中磐石由高冠宇發動進攻後傳給左路的許劉鑑鋒，許劉鑑鋒沿邊線傳中，高冠宇跟進左腳抽射破網，替球隊扳回一城。最終全場比賽結束，台中磐石預備隊1比5南市台鋼綠。"}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2025-04-12-match-060' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "台中磐石足球俱樂部今日（11日）宣佈，上賽季分別效力新北航源的周宇杰加盟俱樂部。"}, {"type": "paragraph", "text": "周宇杰，現年26歲，曾隨中華亞運男足代表隊出戰2018雅加達亞運，亦曾隨航源FC出戰兩屆AFC CUP賽事，比賽經驗相當豐富。"}, {"type": "paragraph", "text": "◈ 球員姓名：周 宇杰（TSOU Yu-Chieh）"}, {"type": "paragraph", "text": "◈ 國籍：台灣"}, {"type": "paragraph", "text": "◈ 出生日期：1998年9月24日（26歲）"}, {"type": "paragraph", "text": "◈ 位置：中場、前鋒"}, {"type": "paragraph", "text": "◈ 曾效力球隊：美崙國中→ 花蓮高中 → 新北航源 → 台中磐石"}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2025-04-11-club-061' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "台中磐石足球俱樂部今日（11日）宣佈，上賽季台灣電力的廖奕盛加盟俱樂部。"}, {"type": "paragraph", "text": "廖奕盛，現年21歲，出身自台中市黎明國中及惠文高中，2022年入選國立台灣體育運動大學，去年隨台灣電力征戰企甲聯賽。"}, {"type": "paragraph", "text": "◈ 球員姓名：廖 奕盛（LIAO Yi-Shen）"}, {"type": "paragraph", "text": "◈ 國籍：台灣"}, {"type": "paragraph", "text": "◈ 出生日期：2003年12月12日（21歲）"}, {"type": "paragraph", "text": "◈ 位置：後衛"}, {"type": "paragraph", "text": "◈ 曾效力球隊：黎明國中 → 惠文高中→ 國立台灣體育運動大學 → 台灣電力 → 台中磐石"}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2025-04-11-club-062' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "台中磐石足球俱樂部今日（11日）宣佈，成功羅致旅德好手王義友，將會隨隊征戰2025總統盃足球錦標賽。"}, {"type": "paragraph", "text": "王義友，台中在地人，現年25歲，曾入選中華男足成年代表隊，2023年亦曾征戰杭州亞運，協助中華隊收下65年首場亞運勝利。"}, {"type": "paragraph", "text": "自2023年起，王義友旅外至德國第五、六級別聯賽，俱樂部希望他作為一眾年青選手的榜樣，並分享他的旅外經驗。"}, {"type": "paragraph", "text": "◈ 球員姓名：王 義友（WANG Yi-You）"}, {"type": "paragraph", "text": "◈ 國籍：台灣"}, {"type": "paragraph", "text": "◈ 出生日期：1999年11月29日（25歲）"}, {"type": "paragraph", "text": "◈ 位置：中後衛"}, {"type": "paragraph", "text": "◈ 曾效力球隊：惠文高中→ 台北市立大學 → 南市台鋼 → 台北紅獅/展逸 → 南市台鋼 → SG Schönebeck（德國） → TuRU Düsseldorf（德國）"}, {"type": "paragraph", "text": "Leistungsträger Wang Yi-You wechselt von Deutschland zu TCRFC"}, {"type": "paragraph", "text": "Der Fußballverein TCRFC gab heute (11. April) bekannt, dass er erfolgreich Wang Yi-You, ein Spieler mit Erfahrung in Deutschland, verpflichtet hat. Er wird das Team beim President‘s Cup 2025 verstärken."}, {"type": "paragraph", "text": "Wang Yi-You, ein 25-jähriger gebürtiger Taichunger, war bereits Teil der A-Nationalmannschaft von Taiwan und nahm 2023 an den Asienspielen in Hangzhou teil, wo er der Nationalmannschaft half, den ersten Sieg bei den Asienspielen seit 65 Jahren einzufahren."}, {"type": "paragraph", "text": "Seit 2023 spielt Wang Yi-You in der deutschen Landesliga. Der Verein hofft, dass er als Vorbild für die vielen jungen Spieler fungiert und seine Auslandserfahrungen mit dem Team teilt."}, {"type": "paragraph", "text": "Taiwanese Talent Wang Yi-You Returns from Germany to Joins TCRFC"}, {"type": "paragraph", "text": "TCRFC announced today (April 11) the successful signing of Taiwanese player Wang Yi-You, who will join the team to compete in the 2025 Presidential Cup."}, {"type": "paragraph", "text": "Wang Yi-You, a native of Taichung, is 25 years old and has previously been selected for the Taiwanese men’s national team. In 2023, he also represented the nation at the Hangzhou Asian Games, helping secure the team’s first victory at the Asian Games in 65 years."}, {"type": "paragraph", "text": "Since 2023, Wang has been playing abroad in German Landesliga. The club hopes he will serve as a role model for the younger players and share his valuable overseas experience."}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2025-04-11-club-063' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "台中磐石新星孫恩祈，日前赴西班牙展開海外訓練行程，先在RC Alcobendas進行為期一週的適應訓練，隨即轉投西協丙球隊Mexico FC深造。經過兩週觀察與實戰磨合，孫恩祈的場上表現與積極態度雙雙獲得教練團肯定，球隊也正式邀請他留隊至本季結束。"}, {"type": "paragraph", "text": "孫恩祈初抵歐洲，先在磐石的西班牙合作夥伴RC Alcobendas展開訓練，快速適應當地球風與節奏。隨後轉赴Mexico FC，一支在西協丙具有競爭力的隊伍，作為一線隊練習生全程參與訓練與戰術演練，更於3月27日的隊內對抗賽中以短傳策動進攻，成功創造一記進球。"}, {"type": "paragraph", "text": "Mexico FC陣中坐擁多位資深好手，包括出身皇家馬德里青訓的Jose Arroyo、曾效力馬德里競技體系多支不同級別球隊的Carlos Morales，以及來自墨西哥豪門America的射手Martin Zuniga，整體實力不容小覷。"}, {"type": "paragraph", "text": "台中磐石對孫恩祈短時間內獲得教練團與隊友認可感到鼓舞，並將全力支援其在西班牙的生活與訓練，期盼他持續進步、穩定成長，在國際舞台發光發熱。"}, {"type": "paragraph", "text": "談到與台灣訓練文化的差異，孫恩祈指出：「在西班牙，練習前都會做多功能重訓，再接著進行正式訓練，一天一堂課、剛好兩小時，其餘時間都是自主練習。」他特別感受到當地球員對訓練的投入程度：「每一堂課大家都拼盡全力，不管是跑位還是對抗，每個人都想表現最好。在這裡，必須每天讓他們看到你的能力，只要你有表現，他們自然會重視你。」"}, {"type": "paragraph", "text": "面對接下來的挑戰，孫恩祈也設定明確方向：「首先要克服語言問題，至少要聽懂場上指令，這樣才能更好融入團隊。其次是精進自己的廚藝。最後就是調適心理，放下對台灣的思念，把全部專注力放在球場上。我相信自己做得到。」"}, {"type": "paragraph", "text": "台中磐石長期致力於協助台灣球員前進國際，拓展視野。俱樂部期望孫恩祈的海外經驗，未來能啟發更多台灣年輕球員勇敢逐夢，同時也為台中、乃至台灣足球整體發展注入更多動能。"}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2025-04-08-international-064' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "台中磐石4月6日北上作客台北迎風足球場，與陽信北競再度交手進行熱身賽。雖然下半場追回一球，但最終仍以1比2吞下敗仗，未能成功扳平。"}, {"type": "paragraph", "text": "比賽開局不利，陽信北競在第13分鐘透過長傳撕破防線先馳得點，10分鐘後陽信北競重施故技，突破磐石疏失紊亂的防線再入一球，短時間內將比分拉開至2比0。第32分鐘台中磐石獲得定位球機會，由柯岳廷起腳射門，但遭對方門將撲出。"}, {"type": "paragraph", "text": "易邊再戰的第1分鐘，磐石抓住陽信北競後場傳球失誤，由陳柏穎前場積極壓迫搶下球權，隨後交給陳治瑋於禁區邊緣起腳破網。然而，磐石在剩餘比賽時間未能創造出具威脅的進攻機會，最終無力扳平，以一球之差落敗。"}, {"type": "paragraph", "text": "這場比賽也提供教練團寶貴的調整參考，磐石將持續積極備戰，以更佳狀態迎接接下來的賽事挑戰。"}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2025-04-07-match-065' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "台中磐石球員梁顥騰近日完成在西班牙RC Alcobendas為期三週的訓練課程，透過實地參與學習當地足球訓練方式與比賽節奏，全面提升自身技術與戰術素養。"}, {"type": "paragraph", "text": "梁顥騰此行首站抵達台中磐石與西班牙合作夥伴RC Alcobendas展開基礎訓練，在台中磐石團隊的安排與協助下，更同步參與另一支同級球隊Zona Norte的晚上訓練，當中包括多場隊內對抗賽，讓他能在短時間內吸收更多比賽經驗。"}, {"type": "paragraph", "text": "「西班牙這邊的控球、傳球節奏，還有跑位和彼此之間的聲音支援，都比我原本預期的高出很多。在這裡如果稍微慢半拍，就會馬上被斷球，所以每個球員動作都得很快速，這讓我的控球技術跟觀察能力都明顯進步。雖然訓練時間有限，但我真的學到很多。在最後一天訓練結束時，我感覺自己比剛來的第一天更加有自信，期待能把這次學習，好好帶回台灣實踐，在球會內好好發揮出來。」"}, {"type": "paragraph", "text": "訓練之餘，梁顥騰也實現了多年夢想，現場觀賞了皇家馬德里的比賽。「能夠看到每一位球星為了勝利不惜耗盡體力、為了進球展現默契，不管誰失誤都會馬上反搶。每個人都在發揮自己的優點，這種高水準比賽真的太精彩，讓我非常感動。」除此之外，亦觀看了馬德里競技對巴塞羅那的西班牙國王盃大戰，感受截然不同的大戰氣氛，了解西班牙足球的不同面向。能夠現場近距離觀摩Lamine Yamal、Pedri、Antoine Griezmann、Julián Alvarez等頂級球星，看他們發揮精湛技術，都讓人大開眼界！"}, {"type": "paragraph", "text": "除了進場看球，台中磐石團隊也前往皇馬體育城參觀這座全球頂級的訓練設施。梁顥騰深受震撼：「我曾經為了踢球跑遍很多地方，但很多時候根本找不到適合的場地。如果有一天台灣也能擁有這樣的訓練基地，那真的是夢想成真。非常感謝俱樂部的安排，讓我們有機會親身體驗世界頂尖足球的樣貌。」"}, {"type": "paragraph", "text": "本次西班牙訓練雖已告一段落，但台中磐石在推動國際交流的腳步仍不會停下。梁顥騰也分享對未來赴歐球員的建議：「想來歐洲訓練、比賽的球員一定要有準備，特別是在語言上，西班牙文或英文能幫助你更快融入、更有效溝通。同時，也要勇敢展現自己，敢傳、敢帶、敢拼，只要努力，就有機會比別人更出色。」"}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2025-04-07-international-066' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "為了備戰即將開打的總統盃，球隊將持續進行多場熱身賽。4月6日（星期日），我們將前往台北迎風足球場，再次與陽信北競進行熱身比賽，共同提升狀態。比賽將於下午3點15分開踢，歡迎球迷們到場觀賽，一起為台灣足球加油！"}, {"type": "paragraph", "text": "陽信北競 Sunny Bank AC Taipei vs 台中磐石 Taichung Rock FC"}, {"type": "paragraph", "text": "日期 Date：2025/4/6（日）"}, {"type": "paragraph", "text": "時間 Time：15:30"}, {"type": "paragraph", "text": "場地 Venue：台北迎風足球場C場 Yingfeng Soccer Field Pitch C熱身賽第三戰 台中磐石對陽信北競"}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2025-04-03-match-067' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "首屆2025年全國總統盃足球錦標賽於4月2日完成分組抽籤，台中磐石積極響應足協號召，將派出台中磐石及台中磐石預備隊雙隊參賽。"}, {"type": "paragraph", "text": "抽籤結果，台中磐石被分入A組，與南市台鋼藍、陽信北競二隊、新北輔大、高大國光NUK同組。而台中磐石預備隊則落入B組，將與台中未來、桃園國際灰、南市台鋼綠及銘傳B展開較量。"}, {"type": "paragraph", "text": "本屆男足賽事將於4月12日正式開幕，每組前兩名將晉級八強淘汰賽，爭奪總統盃榮耀。"}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2025-04-02-match-068' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "總統盃開打前的第三場友誼賽，台中磐石主場對陣陽信北競，磐石雖然上半場有蔡俊昇靠著精彩的進球追成平手，但最終以1比3落敗。"}, {"type": "paragraph", "text": "陽信北競先發球員當中包括有新加盟的前日本U17代表山崎直之，15分鐘，客隊也由他利用間接自由球破門，取得領先。37分鐘，磐石利用長傳進攻，蔡俊昇在禁區邊緣球不著地右腳抽射，幫助台中磐石追成1比1平手。"}, {"type": "paragraph", "text": "台中磐石在下半場作出輪換，讓不同球員保持比賽狀態。而陽信北競在下半場第49分鐘有陳彥睿自由球擊中門框後，由陳開文補射得分。第79分鐘，磐石後衛陳柏崴誤傳遭到對手攔截反擊，客隊最終由李世纓接應左路傳中近門射入。比賽終場比分為台中磐石1比3陽信北競。"}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2025-03-29-match-069' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "台中磐石即將迎來另一場重要的熱身賽，將於3月29日（六）在台中西屯足球場迎戰陽信北競。本場比賽將於下午4點開踢，歡迎各位球迷蒞臨觀戰。"}, {"type": "paragraph", "text": "台中磐石 Taichung Rock FC vs 陽信北競 Sunny Bank AC Taipei"}, {"type": "paragraph", "text": "日期 Date：2025/3/29（六）"}, {"type": "paragraph", "text": "時間 Time：16:00"}, {"type": "paragraph", "text": "場地 Venue：台中西屯足球場 Taichung Xitun Football Field"}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2025-03-22-match-070' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "台中磐石足球俱樂部球員高冠宇獲中華隊徵召，將參加亞洲盃資格賽對土庫曼的賽前集訓。"}, {"type": "paragraph", "text": "這次入選標誌著台中磐石足球俱樂部成立以來，首次有球員入選成年中華隊，對俱樂部而言是一個重要的里程碑。"}, {"type": "paragraph", "text": "高冠宇曾在2023年10月，世界盃資格賽對陣東帝汶時初次登場，表現出色。台中磐石期待他能在中華隊持續發揮實力，為中華隊貢獻力量。"}, {"type": "paragraph", "text": "2027年亞洲盃資格賽中華對戰土庫曼的比賽，將於3月25日18:30在高雄國家體育場舉行，我們邀請所有球迷一起中華隊，為台灣足球加油！"}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2025-03-17-club-071' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "台中磐石足球隊於3月14日（五）晚間7點30分，在台中西屯足球場與台中Futuro進行了一場熱身友誼賽。雖然只是友誼賽，但這場首次上演的「台中德比」依然吸引了近300名球迷進場觀戰，現場氣氛熱烈。"}, {"type": "paragraph", "text": "這場比賽不僅讓兩支球隊透過實戰調整狀態、提升默契，也展現出台中足球發展的潛力與吸引力。台中磐石與台中Futuro都希望透過球隊的努力，讓台中的足球文化更加茁壯，帶動更多人關注這項運動。"}, {"type": "paragraph", "text": "此外，台中磐石將會繼續積極響應台中市政府運動局的發展方向，希望透過足球推廣，促進地方觀光經濟與運動產業發展，共同打造台中成為「酷運動、酷城市」。"}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2025-03-15-match-072' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "台中磐石熱身迎戰台中Futuro 力拚最佳狀態備戰總統盃"}, {"type": "paragraph", "text": "台中磐石將於14日（五）晚間19:30，在台中西屯足球場與台中Futuro進行一場熱身友誼賽。本場比賽是雙方備戰「2025全國總統盃足球錦標賽」的重要測試，透過實戰提升比賽節奏與團隊默契，為即將到來的賽事做好萬全準備。"}, {"type": "paragraph", "text": "總統盃即將在4月12日開踢，台中磐石近期積極備戰，透過移地訓練與熱身賽調整戰術與狀態。本場比賽不僅是檢視訓練進度時刻，也能透過與強隊對抗來提升競技狀態，讓球員適應比賽節奏並加強團隊配合。"}, {"type": "paragraph", "text": "台中磐石教練團表示：「這次是日本集訓回來後的第二場熱身賽，球隊從日本回來後，球員的心態與以往不同，各方面也提升了很多。公開測試日之後也迎來了一些新元素，所以我們很期待與Futuro的比賽。」這場友誼賽將是台中磐石通往總統盃的重要一步，期待球員們在比賽中展現最佳狀態，為即將到來的正式賽事做好準備。"}, {"type": "paragraph", "text": "本場比賽將於台中磐石YouTube頻道進行現場直播，敬請球迷鎖定，為台中足球加油！"}, {"type": "paragraph", "text": "■ 比賽資料"}, {"type": "paragraph", "text": "台中磐石 Taichung Rock vs Taichung Futuro 台中FUTURO"}, {"type": "paragraph", "text": "日期 Date：2025/3/14（五）"}, {"type": "paragraph", "text": "時間 Time：19:30"}, {"type": "paragraph", "text": "場地 Venue：台中西屯足球場 Taichung Xitun Football Field"}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2025-03-13-match-073' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "去年11月，台中磐石足球俱樂部與西班牙 RC Alcobendas 正式宣布建立多層面的策略合作夥伴關係，旨在促進雙方的足球發展，推動國際間的技術與人才交流。"}, {"type": "paragraph", "text": "經過協調與安排後，台中磐石將會在三月派出兩名球員，包括孫恩祈及梁顥騰遠赴西班牙，至RC Alcobendas進行為期三週的訓練。在這段期間，兩位球員將隨著 RC Alcobendas 一線隊進行訓練，學習西班牙足球的各種技術與相關知識。"}, {"type": "paragraph", "text": "球員資料 : 孫恩祈 Sun En-Chi"}, {"type": "paragraph", "text": "■出生：2004年10月11日（20歲）"}, {"type": "paragraph", "text": "■身高：180cm"}, {"type": "paragraph", "text": "■位置：後衛"}, {"type": "paragraph", "text": "梁顥騰 Liang Hao-Teng"}, {"type": "paragraph", "text": "■出生：2003年1月28日（22歲）"}, {"type": "paragraph", "text": "■身高：182cm"}, {"type": "paragraph", "text": "■位置：前鋒"}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2025-03-04-international-074' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "台中磐石致力於為台中足球奠定穩固基礎，我們期望透過專業的培育模式，協助球員發揮潛能，追求卓越。"}, {"type": "paragraph", "text": "這次，我們將與日本東京農業大學足球隊合作，選派四名球員 — 陳瑄廷、龔致宇、李毓霖、李偉綸，前往該隊進行為期兩週的訓練，學習日本足球的訓練方法與比賽模式，進一步提升個人技術與戰術素養。"}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2025-02-28-international-075' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
UPDATE i SET body = N'{"blocks": [{"type": "heading", "text": "日本移地訓練總結"}, {"type": "paragraph", "text": "2月8日，台中磐石展開了俱樂部首次的日本移地訓練。在這次移訓期間，球隊與多支關東地區的大學隊伍以及J聯盟球隊的青訓梯隊進行了一系列比賽。在為期一週的密集訓練與比賽中，全隊獲益良多。"}, {"type": "paragraph", "text": "教練團認為，這次集訓對球隊來說是一次重要的團隊建立機會，也為即將到來的總統盃和企業甲級聯賽打下了堅實的基礎。"}, {"type": "paragraph", "text": "「這次日本移訓帶給球隊很大的衝擊。在這一週的訓練與比賽中，我們深刻體會到日本足球的堅持不懈，這種精神展現在每一次練習、比賽，甚至是每一個細節的處理上。」"}, {"type": "paragraph", "text": "「日本球隊的訓練內容與台灣相差不大，但他們在精神層面與細節處理上的投入，經過長時間的累積，產生了截然不同的效果。」"}, {"type": "paragraph", "text": "俱樂部相信，這次移訓將幫助這支年輕球隊對足球有更深刻的理解，並能以更好的狀態和態度迎接2025總統盃以及2025/26企業甲級聯賽。"}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2025-02-19-international-076' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "台中磐石俱樂部與港超聯球隊九龍城達成協議，隊長楊朝景將轉會至港超賽場。"}, {"type": "paragraph", "text": "這位19歲前鋒在2024賽季台乙聯賽中，總共為球隊上場8場、攻進9顆入球，並贏得台乙聯賽神射手。朝景在去年3月第一次代表中華隊成人隊出賽，至今在國際A級賽總共有2次出賽紀錄，另外在中華隊U20亦有4次出賽、1進球的紀錄。"}, {"type": "paragraph", "text": "根據三方協議，朝景將會暫時繼續參與本俱樂部的訓練及比賽，以保持狀態，並於二月下旬前往九龍城報到。"}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2025-02-04-international-077' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "台中磐石足球俱樂部在1月7日獲得臺中市政府運動局的核准，在合作及冠名上得到認可同意。"}, {"type": "paragraph", "text": "本俱樂部在此感謝臺中市政府運動局的積極回應，期望在未來日子一同推動「足球深耕計畫」，共同深耕六級足球發展，持續促進本市足球運動風氣的成長，同時帶動本市觀光經濟與運動產業，積極打造「酷運動、酷城市」之目標。"}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2025-01-07-club-078' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "台中磐石足球俱樂部欣然宣布，經過俱樂部上下以及各方友好的不遺餘力的協助下，台中磐石通過了中華民國足球協會審查，有條件地通過並取得了甲級俱樂部認證，正式取得2025/26台灣企業甲級足球聯賽的參賽資格。"}, {"type": "paragraph", "text": "台中磐石作為台灣足球的一員，未來必定會以專業及務實的態度努力發展，為台中社區、台灣足球作出貢獻。"}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2024-12-18-club-079' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "在整個賽季裡面，台中磐石在總教練林吉福的帶領下，取得了七勝一和二負，球隊戰績優異並且取得了32個入球之多，攻擊力冠絕乙級聯賽。感謝林教練在本賽季對球隊的用心指導，也恭喜當選聯賽最佳教練。"}, {"type": "paragraph", "text": "楊朝景雖然因U20國家隊的徵召而缺席兩場聯賽，但是在8場比賽當中依然能夠為球隊貢獻了9個入球，並且後來居上取得本屆乙級聯賽的金靴獎。俱樂部對朝景的表現感到滿意，期望他能夠繼續保持謙遜、積極訓練，努力成為更好的選手。"}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2024-12-18-club-080' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "12月7日，迎風河濱公園足球場上演台灣乙級聯賽關鍵一戰，台中磐石必須擊敗銘傳大學Desafio才能取得聯賽冠軍。"}, {"type": "paragraph", "text": "磐石雖然在上半場一度與銘傳大學Desafio爭持不下，但是上半場末段的兩個入球令球隊奠下勝利基礎，然後在下半場再轟七球，最後以9：0擊敗銘傳大學Desafio，刷新本賽季的最大勝利紀錄，並且取得奪冠必須的三分。賽後台中磐石以10戰積22分積分，取得2024 台灣乙級聯賽冠軍。"}, {"type": "paragraph", "text": "台中磐石管理層對球隊能夠達成目標感到無比興奮，這個冠軍全賴教練團，職員以及球員在整個賽季的專注與付出，期望俱樂部以這個冠軍為起點，向更大的目標進發。同時，台中磐石足球俱樂部亦感謝中華民國足球協會在比賽上一直保持專業的安排，令整個賽事得以順利完成。"}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2024-12-07-match-081' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "台中磐石足球俱樂部與西班牙 RC Alcobendas正式宣布建立多領域的策略合作夥伴關係，旨在促進雙方的足球發展，推動國際間的技術與人才交流。本次合作聚焦多個領域，包括青訓發展、球探網絡、技術及戰術交流、提升選手國際賽經驗等，標誌著雙方攜手實現共同目標的新里程。"}, {"type": "paragraph", "text": "台中磐石足球俱樂部負責人馮世文先生表示，此次與 RC Alcobendas 的合作是實行俱樂部宗旨「提高台灣在國際比賽中的競爭力」的重要一步，也是台灣足球邁向國際化的其中一步，期望可以透過這次合作，讓台灣的球員在國際上能順利接軌，持續進步。"}, {"type": "paragraph", "text": "RC Alcobendas副會長Daniel Martin Casas先生表示，RC Alcobendas希望能夠透過這一次的合作，讓台灣的選手有機會前往西班牙訓練，並讓他們體驗到西班牙足球的強度，進而提升台灣足球的水平。未來台中磐石的球員將有機會前往西班牙訓練，並在他們的訓練基地中訓練，並與當地最好的球隊交手，進而幫助到球員、整支球隊。"}, {"type": "paragraph", "text": "關於台中磐石足球俱樂部"}, {"type": "paragraph", "text": "正競逐台灣乙級聯賽的台中磐石足球俱樂部，以提高台灣在國際比賽中的競爭力、塑造台灣在亞洲足球的形象、成為台灣最完整的職業足球俱樂部為目標，積極參與國內外各項賽事，培育優秀的本土選手。"}, {"type": "paragraph", "text": "關於 RC Alcobendas RC Alcobendas 是西班牙一家正競逐馬德里區聯賽的俱樂部，在西班牙以卓越的青訓系統聞名，旗下青訓梯隊分別在Division de Honor、Superliga等頂級聯賽競逐，對手包括皇家馬德里、馬德里競技、巴塞隆納等。"}, {"type": "paragraph", "text": "本次合作標誌著兩家俱樂部攜手共進，創造雙贏的合作模式，為雙方帶來全新機遇與挑戰。"}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2024-11-05-international-082' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
UPDATE i SET body = N'{"blocks": [{"type": "paragraph", "text": "2025/05/17 臺中西屯足球場"}, {"type": "paragraph", "text": "總統盃八強賽：台灣電力 1:1 (PK 4:2) 台中磐石"}, {"type": "paragraph", "text": "進球： 50’ 葉境均(台電) 82’ 施靖堂"}, {"type": "paragraph", "text": "上半場台中磐石展現出色的防守組織，全隊保持高度專注，成功抵禦台電多次從兩翼發動的進攻。面對台電持續透過邊路傳中尋找機會，台中磐石球員的制空能力、來球判讀與即時攔截都相當到位，讓對手始終無法突破防線。儘管雙方在進攻端互有嘗試，但上半場仍未能打開紀錄。"}, {"type": "paragraph", "text": "第50分鐘，台電藉由一次快速反擊突破台中磐石防線，長傳切入禁區後成功抽射破門，先馳得點。第62分鐘，施靖堂開出角球，替補登場的鄭凱議頭槌攻門中柱彈出，與扳平機會擦肩而過。第82分鐘，施靖堂在禁區邊緣個人突破後起腳射門，雖然被守門員撲出，但迅速補射成功破門，將比分扳平為 1:1。由於正規時間未能分出勝負，雙方進入PK大戰。"}, {"type": "paragraph", "text": "在PK大戰中，台電四輪射門全數命中，而台中磐石僅由陳治瑋與廖倢揚射進兩球，最終以總比分 1:1（PK 2:4）惜敗。"}, {"type": "paragraph", "text": "PK戰紀錄 :"}, {"type": "paragraph", "text": "|  |  |  |\n| :-: | :-: | :-: |\n|   | 台灣電力 | 台中磐石 |\n| 第一輪 | 陳昭安 O | 陳治瑋 O |\n| 第二輪 | 涂紹捷 O | 鄭凱議 X |\n| 第三輪 | 葉境均 O | 廖奕盛 X |\n| 第四輪 | 李祥偉 O | 廖倢揚 O |"}, {"type": "paragraph", "text": "先發陣容：3 許魁, 5 周宇杰,13 陳柏崴, 22 黄昱博, 26 林家樂, 42 亞歷山卓, 43 廖倢揚, 45 胡淯翔, 49 張旭揚, 88 廖奕盛, 99 蔡宇翔"}, {"type": "paragraph", "text": "替補 : 2 鄭凱議, 8 陳柏穎, 18 陳冠智, 20 戴彥堯, 27 施靖堂, 28 陳治瑋, 40 林政睿, 41 費威斯, 46 李柏佑"}]}' FROM articles_i18n i JOIN articles a ON a.id = i.article_id WHERE a.slug = N'2025-05-17-match-051' AND i.locale = N'zh-Hant' AND i.body IS NULL;
SET @n += @@ROWCOUNT;
PRINT CONCAT('body rows: ', @n);
SET @n = 0;
